    'A reminder about :class' => 'Isang paalala tungkol sa :class',
    'A reminder is a short, neutral note in the student\'s notifications: some work in this class is past its due date or was handed in late, with a link to their assignments. It never shows marks.' => 'Ang paalala ay isang maikli at neutral na mensahe sa mga abiso ng mag-aaral: may gawain sa klaseng ito na lampas na sa takdang araw o huling naipasa, kasama ang link sa kanilang mga gawain. Hindi ito kailanman nagpapakita ng marka.',
    'A rubric, if you add one, sets this automatically.' => 'Kapag nagdagdag ka ng rubric, ito na ang magtatakda nito.',
    'A school administrator switched it off, for example after a lost phone. If you did not ask for this, tell your school straight away. You can set it up again in Account and preferences.' => 'Ini-off ito ng isang administrador ng paaralan, halimbawa dahil nawala ang phone. Kung hindi mo ito hiniling, sabihan agad ang iyong paaralan. Maaari mo itong i-set up muli sa Account at mga kagustuhan.',
    'A school year can have at most :n grading periods.' => 'Hanggang :n panahon ng pagmamarka lamang ang maaaring magkaroon ang isang taong panuruan.',
    'A section is a grade level\'s group of students, such as Grade 9 Narra. It appears when classes are given that section name. Its adviser can print sign-in and password slips for its students.' => 'Ang seksiyon ay pangkat ng mga mag-aaral sa isang baitang, gaya ng Grade 9 Narra. Lumalabas ito kapag binigyan ng ganoong pangalan ng seksiyon ang mga klase. Makapagpi-print ang adviser nito ng mga slip sa pag-sign in at sa password para sa mga mag-aaral nito.',
    'A short code, for example SCI9.' => 'Maikling code, halimbawa SCI9.',
    'A short note, sent to them as a notification when you save a new or changed reply. They cannot answer it; this is not a chat.' => 'Maikling paalala na ipapadala sa kanila bilang notification kapag nag-save ka ng bago o binagong tugon. Hindi nila ito masasagot; hindi ito chat.',
    'A simple plan built from your upcoming work: two 30-minute sessions before each deadline.' => 'Isang simpleng plano batay sa iyong mga paparating na gawain: dalawang 30 minutong sesyon bago ang bawat takdang araw.',
    'A student\'s AI starts on' => 'Naka-on sa simula ang AI ng mag-aaral',
    'A subject with this name already exists.' => 'May asignatura nang may ganitong pangalan.',
    'A test, task or activity done in class or on paper. Students see it with its date; you type the scores into a grid afterwards.' => 'Pagsusulit, gawain o aktibidad na ginagawa sa klase o sa papel. Nakikita ito ng mga mag-aaral kasama ang petsa nito; ita-type mo ang mga iskor sa isang talaan pagkatapos.',
    'A transmutation table turns the initial grade of a grading period into the grade reported for it. B.E.S.T. Learning and Interactive Study System uses a table only after someone has checked every line against the official order and switched it on. The final grade is then the average of the period grades, as a whole number.' => 'Ginagawa ng talahanayan ng transmutasyon na iniuulat na grado ang paunang grado ng isang panahon ng pagmamarka. Ginagamit lamang ito ng B.E.S.T. Learning and Interactive Study System kapag may nakasuri na sa bawat linya laban sa opisyal na kautusan at pinagana na ito. Ang pangwakas na grado ay ang karaniwan ng mga grado ng bawat panahon, bilang buong numero.',
    'A web page or video. The companion does not read links.' => 'Isang web page o video. Hindi binabasa ng companion ang mga link.',
    'A. Content standards' => 'A. Pamantayang pangnilalaman',
    'A. References' => 'A. Sanggunian',
    'AI can be wrong. Your teacher\'s instructions always take priority, and the companion never decides your grade.' => 'Maaaring magkamali ang AI. Laging nauuna ang mga tagubilin ng iyong guro, at hindi kailanman ang companion ang nagpapasya ng iyong grado.',
    'AI can make mistakes. Your teacher\'s instructions come first.' => 'Maaaring magkamali ang AI. Mauna ang mga tagubilin ng iyong guro.',
    'AI companion' => 'AI companion',
    'AI companion and guardian\'s answer for :name' => 'AI companion at sagot ng magulang o guardian para kay :name',
    'AI demo mode means no AI service is connected. The companion finds the most relevant passages in your released class materials and shows them with their real sources, and practice items are made from those passages. It does not write new explanations. A school administrator can connect an AI provider in the server configuration.' => 'Ang AI demo mode ay nangangahulugang walang nakakonektang AI service. Hinahanap ng companion ang mga pinakaangkop na sipi sa mga inilabas na materyal ng iyong klase at ipinapakita ang mga ito kasama ang tunay nilang sanggunian, at mula sa mga siping iyon binubuo ang mga pagsasanay. Hindi ito sumusulat ng mga bagong paliwanag. Maaaring magkonekta ng AI provider ang administrador ng paaralan sa configuration ng server.',
    'AI draft, not approved' => 'Burador ng AI, hindi pa aprubado',
    'AI draft, reviewed' => 'Draft ng AI, nasuri na',
    'AI draft: needs review' => 'Draft ng AI: kailangang suriin',
    'AI drafts of lessons and questions stay drafts until you review and publish them. AI grading help is a suggestion you can accept, change or ignore.' => 'Nananatiling draft ang mga aralin at tanong na binuo ng AI hanggang suriin at i-publish mo ang mga ito. Ang tulong ng AI sa pagmamarka ay mungkahi lamang na maaari mong tanggapin, baguhin o balewalain.',
    'AI drafts of questions, lessons and feedback are suggestions. Read and correct them before students see anything.' => 'Mungkahi lamang ang mga draft ng AI na tanong, aralin at feedback. Basahin at itama ang mga ito bago may makita ang mga mag-aaral.',
    'AI is in demo mode, so answers are built from class materials without an AI model.' => 'Naka-demo mode ang AI, kaya ang mga sagot ay binubuo mula sa mga materyal ng klase nang walang AI model.',
    'AI is switched off for this student, so their work is not sent to an AI service.' => 'Naka-off ang AI para sa mag-aaral na ito, kaya hindi ipinapadala sa AI service ang kanyang gawain.',
    'AI provider' => 'AI provider',
    'AI teaching tools are turned off at your school.' => 'Naka-off ang mga AI tool sa pagtuturo sa iyong paaralan.',
    'AI this month' => 'AI ngayong buwan',
    'AI tools are on' => 'Naka-on ang mga AI tool',
    'AI tools are turned off at your school.' => 'Naka-off ang mga AI tool sa iyong paaralan.',
    'AI usage' => 'Paggamit ng AI',
    'AI_PROVIDER has an unknown value. Use demo, anthropic or openai_compatible.' => 'Hindi kilala ang value ng AI_PROVIDER. Gamitin ang demo, anthropic o openai_compatible.',
