    'Account and preferences lets you choose larger text, reduced motion, underlined links, and your language.' => 'Sa Account at mga kagustuhan, maaari mong piliin ang mas malaking teksto, mas kaunting galaw, mga link na may salungguhit, at ang iyong wika.',
    'Account created' => 'Nagawa ang account',
    'Account details' => 'Mga detalye ng account',
    'Account details can be changed on the person\'s account page. Grades and feedback are corrected by the class teacher; contact them if the request is about a grade.' => 'Mababago ang mga detalye ng account sa pahina ng account ng tao. Ang guro ng klase ang nagtatama ng mga grado at feedback; makipag-ugnayan sa kanya kung tungkol sa grado ang kahilingan.',
