    'Active: students or teachers who did anything B.E.S.T. Learning and Interactive Study System records that week, such as signing in, opening a material, handing in work or asking the companion.' => 'Aktibo: mga mag-aaral o guro na may ginawang itinatala ng B.E.S.T. Learning and Interactive Study System noong linggong iyon, gaya ng pag-sign in, pagbukas ng materyal, pagpasa ng gawain o pagtatanong sa companion.',
    'Activities' => 'Mga gawain',
    'Activity shows actions such as sign-ins and submissions. Companion conversations are private and are not shown here.' => 'Ipinapakita ng aktibidad ang mga aksiyon gaya ng pag-sign in at pagpasa. Pribado ang mga usapan sa companion at hindi ipinapakita rito.',
