    'Adjust' => 'Isaayos',
    'Administrators' => 'Mga administrador',
    'Administrators cannot be added to classes.' => 'Hindi maidaragdag sa mga klase ang mga administrador.',
    'Administrators do not belong to classes.' => 'Hindi kasapi ng mga klase ang mga administrador.',
    'Adviser' => 'Adviser',
    'Adviser of :section' => 'Adviser ng :section',
    'Adviser saved.' => 'Na-save ang adviser.',
    'Advisers and administrators can switch it off for one student, for example when a guardian says no. Untick to keep it off for each student until one of them switches it on, for example after a guardian says yes.' => 'Maaari itong i-off ng mga adviser at administrador para sa isang mag-aaral, halimbawa kapag tumanggi ang magulang o guardian. Alisin ang tsek para manatili itong naka-off sa bawat mag-aaral hanggang i-on ito ng isa sa kanila, halimbawa pagkatapos pumayag ang magulang o guardian.',
    'Advisory' => 'Advisory',
    'After submitting' => 'Pagkapasa',
    'After the due date' => 'Pagkatapos ng takdang araw',
    'After you submit, you cannot change your work unless your teacher returns it.' => 'Kapag naipasa mo na, hindi mo na mababago ang iyong gawa maliban kung ibalik ito ng iyong guro.',
    'After your password, B.E.S.T. Learning and Interactive Study System can also ask for a code from an app on your phone, so a password someone else learns is not enough to sign in as you. Recommended for administrators.' => 'Pagkatapos ng iyong password, maaari ring humingi ang B.E.S.T. Learning and Interactive Study System ng code mula sa isang app sa iyong phone, kaya hindi sapat ang password na malaman ng iba para makapag-sign in bilang ikaw. Inirerekomenda para sa mga administrador.',
    'After your password, B.E.S.T. Learning and Interactive Study System will also ask for a code from an app on your phone. Someone who learns your password still cannot sign in as you.' => 'Pagkatapos ng iyong password, hihingi rin ang B.E.S.T. Learning and Interactive Study System ng code mula sa isang app sa iyong phone. Hindi pa rin makakapag-sign in bilang ikaw ang taong makaalam ng iyong password.',
