    'An AI draft' => 'Draft ng AI',
    'An AI provider is connected, so the companion writes new answers. They are still checked against your class materials when you ask about them.' => 'May nakakonektang AI provider, kaya sumusulat ang companion ng mga bagong sagot. Inihahambing pa rin ang mga ito sa mga materyal ng iyong klase kapag nagtanong ka tungkol sa mga ito.',
    'An empty score removes a score saved earlier. A student with a score is no longer marked absent.' => 'Ang blangkong iskor ay nag-aalis ng iskor na na-save dati. Ang mag-aaral na may iskor ay hindi na nakatalang lumiban.',
    'An export can only be prepared for an open export request.' => 'Maihahanda lamang ang export para sa isang bukas na kahilingan sa export.',
    'An idea' => 'Isang ideya',
    'Announcement deleted.' => 'Nabura ang anunsiyo.',
    'Announcement posted. Students have been notified in B.E.S.T. Learning and Interactive Study System.' => 'Nai-post ang anunsiyo. Naabisuhan na ang mga mag-aaral sa B.E.S.T. Learning and Interactive Study System.',
    'Announcements' => 'Mga anunsiyo',
