    'Answer quizzes yourself. Do not share quiz questions or answers while a quiz is open, and do not ask anyone, or the companion, to answer for you.' => 'Ikaw mismo ang sumagot sa mga quiz. Huwag ibahagi ang mga tanong o sagot sa quiz habang bukas ito, at huwag magpasagot sa iba o sa companion.',
