    'Answers' => 'Mga sagot',
    'Answers can then use this class\'s released materials, with sources.' => 'Magagamit ng mga sagot ang mga inilabas na materyal ng klaseng ito, may kasamang sanggunian.',
    'Answers drawn only from your released class materials, with sources.' => 'Mga sagot na mula lamang sa mga inilabas na materyal ng iyong klase, may kasamang sanggunian.',
