    'Answers released: :title' => 'Inilabas ang mga sagot: :title',
    'Answers save as you go and stay on this device if the connection drops.' => 'Nase-save ang mga sagot habang sumasagot ka at nananatili sa device na ito kapag naputol ang koneksiyon.',
    'Answers saved.' => 'Na-save ang mga sagot.',
    'Answers shown' => 'Pagpapakita ng sagot',
    'Answers students or teachers flagged as wrong or unsafe.' => 'Mga sagot na minarkahan ng mga mag-aaral o guro bilang mali o hindi ligtas.',
    'Answers that never reached the server, for example because the connection dropped as time ran out, are not part of this attempt. If that happened, tell your teacher: they can reopen the attempt.' => 'Hindi kasama sa pagtatangkang ito ang mga sagot na hindi umabot sa server, halimbawa dahil naputol ang koneksiyon nang maubos ang oras. Kung nangyari iyon, sabihan ang iyong guro: maaari niyang muling buksan ang pagtatangka.',
    'Answers that reached your teacher' => 'Mga sagot na umabot sa iyong guro',
    'Answers you gave earlier on this device were restored and are being sent.' => 'Naibalik ang mga sagot na ibinigay mo kanina sa device na ito at ipinapadala na.',
    'Any authenticator app works, for example Google Authenticator or Microsoft Authenticator. They are free, and they work without mobile data.' => 'Gagana ang kahit anong authenticator app, halimbawa ang Google Authenticator o Microsoft Authenticator. Libre ang mga ito, at gumagana kahit walang mobile data.',
    'Any grade' => 'Anumang baitang',
