    'Draft ready. Read and edit every section before publishing; students see nothing until you do.' => 'Handa na ang draft. Basahin at i-edit ang bawat bahagi bago i-publish; walang makikita ang mga mag-aaral hangga\'t hindi mo ito ginagawa.',
