    'Drafting…' => 'Binubuo…',
    'Drafts' => 'Mga draft',
    'Drafts are for you to review and adapt. Nothing is shared with students.' => 'Ang mga draft ay para suriin at iangkop mo. Walang ibinabahagi sa mga mag-aaral.',
    'Drafts stay private until you publish. Students see published work from its opening date.' => 'Pribado ang mga draft hanggang i-publish mo. Makikita ng mga mag-aaral ang na-publish na gawain simula sa petsa ng pagbubukas nito.',
    'Due' => 'Takdang araw',
