    'Due :date' => 'Takdang araw: :date',
    'Due :day at :time' => 'Takdang araw: :day, :time',
    'Due :time' => 'Takdang oras: :time',
    'Due dates and reminders use this unless a person sets their own.' => 'Ito ang ginagamit ng mga takdang araw at paalala maliban kung nagtakda ang isang tao ng sarili niyang timezone.',
    'Due dates and your own study sessions, in :tz time.' => 'Mga takdang araw at sarili mong mga sesyon ng pag-aaral, sa oras ng :tz.',
    'Due soon' => 'Malapit na ang takdang araw',
    'Due soon: :title' => 'Malapit na ang takdang araw: :title',
    'Due today at :time' => 'Takdang araw ngayon, :time',
    'Due tomorrow at :time' => 'Takdang araw bukas, :time',
    'Duplicate' => 'Gumawa ng kopya',
    'Duplicated an assignment' => 'Gumawa ng kopya ng gawain',
    'Each bar is the share of correct answers to automatically marked questions tagged with that topic, across all submitted attempts. A topic is flagged when at least :n students answered and fewer than :pct% of answers were correct.' => 'Ang bawat bar ay ang bahagdan ng tamang sagot sa mga tanong na awtomatikong minamarkahan at may ganoong paksa, mula sa lahat ng naipasang pagtatangka. Nilalagyan ng tanda ang isang paksa kapag hindi bababa sa :n mag-aaral ang sumagot at mas mababa sa :pct% ng mga sagot ang tama.',
    'Each category needs a name and a weight between 0 and 100.' => 'Kailangan ng bawat kategorya ng pangalan at timbang na mula 0 hanggang 100.',
    'Each category\'s percentage counts by its weight. Teachers pick a category for each assignment.' => 'Binibilang ang porsiyento ng bawat kategorya ayon sa timbang nito. Pumipili ang mga guro ng kategorya para sa bawat gawain.',
    'Each class is one section of a subject. Teachers and students only see the classes they belong to.' => 'Ang bawat klase ay isang seksiyon ng isang asignatura. Nakikita lamang ng mga guro at mag-aaral ang mga klaseng kinabibilangan nila.',
    'Each code works once, and whoever holds a slip can set the password, so hand slips out in person and keep any you could not give out. Printing new slips for someone cancels their old one. This page shows the codes until :time.' => 'Isang beses lang gumagana ang bawat code, at kung sino ang may hawak ng slip ay makapagtatakda ng password, kaya personal na ipamigay ang mga slip at itabi ang hindi naipamigay. Kapag nag-print ng bagong slip para sa isang tao, makakansela ang luma niya. Ipinapakita ng pahinang ito ang mga code hanggang :time.',
    'Each code works once. If yours does not work, ask for a new slip; the old one stops working.' => 'Isang beses lang gumagana ang bawat code. Kung hindi gumana ang sa iyo, humingi ng bagong slip; titigil sa paggana ang luma.',
    'Each criterion needs points between 0.5 and 100.' => 'Kailangang may puntos na mula 0.5 hanggang 100 ang bawat pamantayan.',
    'Each descriptor needs a label and a lowest grade between 0 and 100.' => 'Kailangan ng bawat deskriptor ng label at pinakamababang grado na mula 0 hanggang 100.',
    'Each dot is one released result as a percentage of its points, oldest to newest. Latest :last%; average :avg% across :n results.' => 'Bawat tuldok ay isang inilabas na resulta bilang porsiyento ng puntos nito, mula pinakaluma hanggang pinakabago. Pinakahuli :last%; karaniwan :avg% sa :n resulta.',
    'Each grading period grade is transmuted with the school\'s table.' => 'Tina-transmute ang grado ng bawat panahon ng pagmamarka gamit ang talahanayan ng paaralan.',
    'Each grading period\'s grade uses only the released work from that period.' => 'Ang grado ng bawat panahon ng pagmamarka ay mula lamang sa mga inilabas na gawain sa panahong iyon.',
    'Each group needs a name.' => 'Kailangan ng bawat pangkat ng pangalan.',
    'Each group\'s weights must add up to 100. Leave a row empty to remove it.' => 'Dapat umabot sa 100 ang kabuuan ng mga timbang ng bawat pangkat. Iwanang blangko ang isang hilera para alisin ito.',
    'Each period grade is transmuted with your school\'s table. The final grade is their average, as a whole number.' => 'Tina-transmute ang grado ng bawat panahon gamit ang talahanayan ng iyong paaralan. Ang pangwakas na grado ay ang karaniwan ng mga ito, bilang buong numero.',
    'Each person gets a one-time code to set a password. It works once and expires in :days days. Print the slips, cut them apart and hand each one to its owner, or share each link privately. The slips and links are available here for the next 30 minutes; after that, print new ones from a class roster or a person\'s page.' => 'Bawat tao ay may isang beses na code para magtakda ng password. Isang beses lang itong gumagana at mag-e-expire sa loob ng :days araw. I-print ang mga slip, gupitin, at ibigay ang bawat isa sa may-ari, o ibahagi nang pribado ang bawat link. Makukuha rito ang mga slip at link sa susunod na 30 minuto; pagkatapos noon, mag-print ng bago mula sa roster ng klase o sa pahina ng tao.',
    'Each question can be tagged with the one competency it assesses, and each lesson with those it teaches (on the question in the assignment\'s editor, and in the lesson\'s details). The share is of correct answers to automatically marked questions with that competency, in submitted work. A competency is flagged when at least :n students answered and fewer than :pct% of answers were correct.' => 'Maaaring lagyan ang bawat tanong ng iisang kasanayang sinusukat nito, at ang bawat aralin ng mga kasanayang itinuturo nito (sa tanong sa editor ng gawain, at sa mga detalye ng aralin). Ang bahagdan ay ng mga tamang sagot sa mga tanong na awtomatikong minamarkahan na may ganoong kasanayan, sa mga ipinasang gawain. Minamarkahan ang isang kasanayan kapag hindi bababa sa :n mag-aaral ang sumagot at mas mababa sa :pct% ng mga sagot ang tama.',
    'Each slip gets a new one-time code; earlier slips or links for these students stop working.' => 'Bawat slip ay may bagong isang beses na code; titigil sa paggana ang mga naunang slip o link ng mga mag-aaral na ito.',
