    'Feedback released: :title' => 'Inilabas ang feedback: :title',
    'Feedback you already gave students keeps this text.' => 'Mananatili ang tekstong ito sa feedback na naibigay mo na sa mga mag-aaral.',
    'Feedback you send appears here with its status and any reply.' => 'Lalabas dito ang feedback na ipapadala mo kasama ang katayuan nito at anumang tugon.',
    'Feedback you sent' => 'Feedback na naipadala mo',
    'Feedback you write often, saved once. Insert them while grading, then make each one fit the student\'s work. Only you see your comment bank.' => 'Ang feedback na madalas mong isulat, isang beses lang ise-save. Isingit ang mga ito habang nagmamarka, saka iangkop ang bawat isa sa gawa ng mag-aaral. Ikaw lamang ang nakakakita ng iyong bangko ng komento.',
    'Feedback: confusing' => 'Feedback: nakalilito',
