    'Flashcards' => 'Flashcards',
    'Flashcards are made here from your class materials. Check the class, then press Flashcards.' => 'Dito ginagawa ang flashcards mula sa mga materyal ng iyong klase. Tingnan ang klase, saka pindutin ang Flashcards.',
    'Flashcards are the one kind you mark yourself. Be honest: a card you knew comes back later.' => 'Ang flashcards lamang ang ikaw mismo ang nagmamarka. Maging tapat: babalik nang mas huli ang kard na alam mo.',
    'Flashcards from your materials:' => 'Mga flashcard mula sa iyong mga materyal:',
    'Flashcards: :t' => 'Flashcards: :t',
    'Focus on' => 'Tumuon sa',
    'Focus on one material' => 'Tumuon sa isang materyal',
    'Follow the school' => 'Sundin ang paaralan',
    'For :name. Changing it signs you out on other devices.' => 'Para kay :name. Kapag binago ito, masa-sign out ka sa ibang device.',
    'For example when time ran out while the student was offline. Their saved answers stay; marks are cleared until they submit again. The time starts when they open it.' => 'Halimbawa, kapag naubos ang oras habang offline ang mag-aaral. Mananatili ang mga na-save niyang sagot; buburahin ang mga marka hanggang ipasa niya itong muli. Magsisimula ang oras kapag binuksan niya ito.',
    'For example, what you still find confusing.' => 'Halimbawa, kung ano pa ang nakalilito sa iyo.',
    'For example, which pages matter for the next quiz.' => 'Halimbawa, kung aling mga pahina ang mahalaga para sa susunod na quiz.',
    'For example: A group lab on breathing rates' => 'Halimbawa: Isang group lab tungkol sa bilis ng paghinga',
    'For example: Clear data table; the conclusion needs evidence from the data' => 'Halimbawa: Malinaw ang data table; kailangan ng ebidensya mula sa datos ang konklusyon',
    'For example: Five quadratic equations to solve by factoring' => 'Halimbawa: Limang quadratic equation na lulutasin sa pamamagitan ng factoring',
    'For example: Grade 9' => 'Halimbawa: Baitang 9',
    'For example: Grade 9 Science, heredity, 60 minutes' => 'Halimbawa: Baitang 9 Science, heredity, 60 minuto',
    'For example: How does the heart pump blood?' => 'Halimbawa: Paano nagbobomba ng dugo ang puso?',
    'For example: Just the main ideas, in short points' => 'Halimbawa: Ang mga pangunahing ideya lang, sa maiikling punto',
    'For example: Punnett squares' => 'Halimbawa: Punnett square',
    'For example: Science quiz on Friday. I am free after 5 PM.' => 'Halimbawa: Quiz sa Science sa Biyernes. Libre ako pagkatapos ng 5 PM.',
    'For example: Solve 2x + 3 = 11' => 'Halimbawa: Lutasin ang 2x + 3 = 11',
    'For example: What does the module say about the alveoli?' => 'Halimbawa: Ano ang sinasabi ng module tungkol sa alveoli?',
    'For example: Why the walls of the alveoli are thin' => 'Halimbawa: Kung bakit manipis ang dingding ng alveoli',
    'For example: allele, genotype, phenotype' => 'Halimbawa: allele, genotype, phenotype',
    'For example: at grade level' => 'Halimbawa: ayon sa baitang',
    'For example: discussion and pair work' => 'Halimbawa: talakayan at gawaing magkapareha',
    'For example: gas exchange' => 'Halimbawa: pagpapalitan ng gas',
    'For example: practise Punnett squares' => 'Halimbawa: magsanay sa Punnett square',
    'For school administrators' => 'Para sa mga administrador ng paaralan',
    'For students' => 'Para sa mga mag-aaral',
    'For students who did this on a printed copy instead of online. Students who handed it in online keep their online grading.' => 'Para sa mga mag-aaral na gumawa nito sa naka-print na kopya sa halip na online. Mananatili ang online na pagmamarka ng mga nagpasa online.',
    'For teachers' => 'Para sa mga guro',
    'For teachers and administrators' => 'Para sa mga guro at administrador',
    'For the whole school. 0 means no budget. Demo mode uses no tokens.' => 'Para sa buong paaralan. Ang 0 ay nangangahulugang walang itinakdang budget. Hindi gumagamit ng token ang demo mode.',
    'Forgot your password? Ask your teacher, adviser or school administrator for a new sign-in slip.' => 'Nakalimutan ang password? Humingi ng bagong slip sa pag-sign in sa iyong guro, adviser o administrador ng paaralan.',
    'Format' => 'Paraan ng pagtuturo',
    'Former account' => 'Dating account',
    'From' => 'Mula',
    'From :file. Nothing has been saved yet.' => 'Mula sa :file. Wala pang na-save.',
    'From :source.' => 'Mula sa :source.',
    'From :title' => 'Mula sa :title',
    'From grade' => 'Mula sa grado',
    'From submitted work only. These describe questions and topics, not students, and small groups can swing a lot.' => 'Mula lamang sa mga naipasang gawain. Inilalarawan ng mga ito ang mga tanong at paksa, hindi ang mga mag-aaral, at maaaring malaki ang pagbabago ng resulta sa maliliit na grupo.',
    'From your class materials' => 'Mula sa mga materyal ng iyong klase',
    'Front' => 'Harap',
    'Full history' => 'Buong kasaysayan',
    'Gave a student their own due date or extra time' => 'Binigyan ang isang mag-aaral ng sariling takdang araw o dagdag na oras',
    'General explanation' => 'Pangkalahatang paliwanag',
    'Get a hint' => 'Humingi ng pahiwatig',
    'Get a question right and it comes back after :days days, a little longer each time. Miss it and it comes back tomorrow, one step lower. After the last step it leaves your queue.' => 'Kapag tama ang sagot mo, babalik ang tanong pagkalipas ng :days araw, medyo mas matagal sa bawat pagkakataon. Kapag mali, babalik ito bukas, isang hakbang na mas mababa. Pagkatapos ng huling hakbang, aalis na ito sa iyong pila.',
    'Get a suggested score for each rubric criterion, with reasons. The student\'s typed answer is sent to the AI service without their name.' => 'Kumuha ng mungkahing iskor para sa bawat pamantayan ng rubric, kasama ang mga dahilan. Ipapadala sa AI service ang tinipang sagot ng mag-aaral nang wala ang kanyang pangalan.',
    'Get new ideas' => 'Kumuha ng mga bagong ideya',
    'Getting help' => 'Paghingi ng tulong',
    'Give :group a weight between 0 and 100 for every category.' => 'Bigyan ang :group ng timbang na mula 0 hanggang 100 sa bawat kategorya.',
    'Give a student who was absent their own make-up date, or excuse them. Until the make-up date they are not counted as absent. Excused work is not counted and never shows as missing. No reason is recorded.' => 'Bigyan ang mag-aaral na lumiban ng sarili niyang petsa ng make-up, o palibrehin siya. Hanggang sa petsa ng make-up, hindi siya binibilang na lumiban. Hindi binibilang ang pinalibreng gawain at hindi ito kailanman lumalabas na kulang. Walang dahilang itinatala.',
    'Give me a hint' => 'Bigyan mo ako ng pahiwatig',
    'Give one student their own due date or extra minutes on the time limit, or excuse them. They see their own dates everywhere; excused work is not counted and never shows as missing. No reason is recorded.' => 'Bigyan ang isang mag-aaral ng sariling takdang araw o dagdag na minuto sa takdang oras, o palibrehin siya. Makikita niya ang sarili niyang mga petsa saanman; hindi binibilang ang pinalibreng gawain at hindi ito lumalabas na hindi naipasa. Walang itinatalang dahilan.',
    'Give one student their own due date, or excuse them. They see their own date everywhere; excused work is not counted and never shows as missing. No reason is recorded.' => 'Bigyan ang isang mag-aaral ng sariling takdang araw, o palibrehin siya. Makikita niya ang sarili niyang petsa saanman; hindi binibilang ang pinalibreng gawain at hindi ito lumalabas na hindi naipasa. Walang itinatalang dahilan.',
    'Give your classes a section name, such as Narra, on each class page. The section appears here so you can choose its adviser.' => 'Bigyan ng pangalan ng seksiyon ang iyong mga klase, gaya ng Narra, sa pahina ng bawat klase. Lalabas dito ang seksiyon para mapili mo ang adviser nito.',
    'Given and family names are required.' => 'Kailangan ang unang pangalan at apelyido.',
    'Given name' => 'Unang pangalan',
    'Go back' => 'Bumalik',
    'Go to classes' => 'Pumunta sa mga klase',
    'Go to sign in' => 'Pumunta sa pag-sign in',
