    'Google sign-in' => 'Pag-sign in gamit ang Google',
    'Google sign-in could not be checked. Try again, or sign in with your password.' => 'Hindi masuri ang pag-sign in gamit ang Google. Subukang muli, o mag-sign in gamit ang iyong password.',
    'Google sign-in could not be completed. Try again, or sign in with your password.' => 'Hindi natapos ang pag-sign in gamit ang Google. Subukang muli, o mag-sign in gamit ang iyong password.',
