    'Grades and comments appear here when your teachers release them.' => 'Lalabas dito ang mga grado at komento kapag inilabas na ng iyong mga guro.',
    'Grades and feedback appear when your teacher releases them.' => 'Lalabas ang mga grado at feedback kapag inilabas na ng iyong guro.',
    'Grades for :name, :period' => 'Mga grado ni :name, :period',
    'Grades shown' => 'Pagpapakita ng grado',
    'Grades use only results teachers have released.' => 'Mula lamang sa mga resultang inilabas na ng mga guro ang mga grado.',
    'Grades, submissions and class records are kept for as long as the school\'s records policy requires.' => 'Itinatago ang mga grado, ipinasang gawain at talaan ng klase hangga\'t kinakailangan ng patakaran ng paaralan sa pag-iingat ng mga talaan.',
    'Grading' => 'Pagmamarka',
    'Grading category' => 'Kategorya ng pagmamarka',
    'Grading model' => 'Paraan ng pagmamarka',
    'Grading period' => 'Panahon ng pagmamarka',
    'Grading period added.' => 'Naidagdag ang panahon ng pagmamarka.',
    'Grading period removed. Work a teacher had placed in it now counts by its due date.' => 'Inalis ang panahon ng pagmamarka. Ang mga gawaing inilagay rito ng guro ay binibilang na ngayon ayon sa takdang araw nito.',
    'Grading period saved. Work moves to the period its due date now falls in.' => 'Na-save ang panahon ng pagmamarka. Lilipat ang mga gawain sa panahong sumasaklaw ngayon sa takdang araw nito.',
    'Grading periods' => 'Mga panahon ng pagmamarka',
    'Grading periods, category weights, weights by subject group and the transmutation table have their own page.' => 'May sariling pahina ang mga panahon ng pagmamarka, ang timbang ng mga kategorya, ang timbang ayon sa pangkat ng asignatura at ang talahanayan ng transmutasyon.',
    'Grading sections' => 'Mga bahagi ng pagmamarka',
    'Grading setup saved. Gradebooks use it right away.' => 'Na-save ang setup sa pagmamarka. Agad itong gagamitin ng mga talaan ng grado.',
    'Grading suggestions' => 'Mga mungkahi sa pagmamarka',
    'Group' => 'Pangkat',
    'Group :n name' => 'Pangalan ng pangkat :n',
    'Group of each subject' => 'Pangkat ng bawat asignatura',
    'Groups of subjects can weigh the categories differently, as DepEd\'s orders do. A subject without a group uses the default weights above.' => 'Maaaring magkaiba ang timbang ng mga kategorya sa bawat pangkat ng asignatura, gaya ng sa mga kautusan ng DepEd. Ginagamit ng asignaturang walang pangkat ang default na timbang sa itaas.',
    'Guardian\'s answer' => 'Sagot ng magulang o guardian',
    'Guide me step by step' => 'Gabayan ako nang hakbang-hakbang',
    'Hand in work that is your own. You may use the companion to understand a topic, practise and plan, but not to write graded work for you.' => 'Ipasa ang sarili mong gawa. Maaari mong gamitin ang companion para maunawaan ang isang paksa, magsanay at magplano, pero hindi para isulat ang may-gradong gawain para sa iyo.',
    'Handed in' => 'Naipasa',
    'Handed in late' => 'Naipasa nang huli',
    'Handed in late (%)' => 'Naipasa nang huli (%)',
    'Handed in on time' => 'Naipasa sa takdang oras',
    'Handed in on time (%)' => 'Naipasa sa oras (%)',
    'Handed in online' => 'Ipinasa online',
    'Handed in work' => 'Nagpasa ng gawain',
    'Have a sign-in slip? Type its code' => 'May slip ka sa pag-sign in? I-type ang code nito',
    'Held' => 'Nakabinbin',
    'Hello :name,' => 'Kumusta, :name,',
    'Help' => 'Tulong',
    'Help me make a study plan' => 'Tulungan akong gumawa ng plano sa pag-aaral',
    'Help me prepare: :topic' => 'Tulungan akong maghanda: :topic',
    'Help me understand: :topic' => 'Tulungan akong maunawaan: :topic',
    'Help message' => 'Mensahe ng tulong',
    'Hidden from students and the companion until the date below.' => 'Nakatago sa mga mag-aaral at sa companion hanggang sa petsa sa ibaba.',
    'Hidden: fewer than :n expected submissions' => 'Nakatago: mas kaunti sa :n inaasahang pagpasa',
    'Hide from the subject list for new classes.' => 'Itago sa listahan ng asignatura para sa mga bagong klase.',
    'History' => 'Kasaysayan',
    'Home' => 'Home',
    'Home shows what is due soon and where you left off. Assignments lists everything, with filters for upcoming, submitted, graded and overdue work.' => 'Ipinapakita ng Home ang malapit nang ipasa at kung saan ka huminto. Nakalista sa Mga gawain ang lahat, may filter para sa paparating, naipasa, may grado at lampas na sa takdang araw.',
    'Hours before a due date that students get a reminder. 0 turns reminders off.' => 'Ilang oras bago ang takdang araw makatatanggap ng paalala ang mga mag-aaral. Ino-off ng 0 ang mga paalala.',
    'How :school uses B.E.S.T. Learning and Interactive Study System, what information it keeps about you, and what you can do about it.' => 'Kung paano ginagamit ng :school ang B.E.S.T. Learning and Interactive Study System, anong impormasyon tungkol sa iyo ang itinatago nito, at ano ang maaari mong gawin tungkol dito.',
    'How B.E.S.T. Learning and Interactive Study System is used across the school, week by week from Monday to Sunday. Counts only: no rankings and no lists of students. A number that comes from fewer than :n people is hidden.' => 'Kung paano ginagamit ang B.E.S.T. Learning and Interactive Study System sa buong paaralan, linggo-linggo mula Lunes hanggang Linggo. Bilang lamang: walang ranggo at walang listahan ng mga mag-aaral. Nakatago ang bilang na galing sa mas kaunti sa :n tao.',
    'How B.E.S.T. Learning and Interactive Study System works and where to get help.' => 'Kung paano gumagana ang B.E.S.T. Learning and Interactive Study System at saan hihingi ng tulong.',
    'How a grade is worked out' => 'Paano kinukuwenta ang grado',
    'How grades are worked out at your school. B.E.S.T. Learning and Interactive Study System does not assume a policy: the periods, weights and table here are your school\'s, and teachers still decide each score.' => 'Kung paano kinukuwenta ang mga grado sa iyong paaralan. Walang ipinapalagay na patakaran ang B.E.S.T. Learning and Interactive Study System: sa iyong paaralan ang mga panahon, timbang at talahanayan dito, at ang mga guro pa rin ang nagpapasya ng bawat iskor.',
    'How long it is kept' => 'Gaano ito katagal itinatago',
    'How long that service keeps request data, and whether it may use it, depends on the school\'s agreement with the provider. Ask the contact above for details. B.E.S.T. Learning and Interactive Study System does not use your conversations to train any model.' => 'Nakadepende sa kasunduan ng paaralan at ng provider kung gaano katagal itinatago ng serbisyong iyon ang datos ng mga kahilingan, at kung maaari nitong gamitin ito. Magtanong sa contact na nabanggit sa itaas para sa mga detalye. Hindi ginagamit ng B.E.S.T. Learning and Interactive Study System ang iyong mga usapan para sanayin ang anumang model.',
    'How reviews work' => 'Paano gumagana ang pagbabalik-aral',
    'How students answered' => 'Paano sumagot ang mga mag-aaral',
    'How students do it' => 'Paano ito ginagawa ng mga mag-aaral',
    'How students submit' => 'Paano magpapasa ang mga mag-aaral',
    'How the AI companion uses your information' => 'Paano ginagamit ng AI companion ang iyong impormasyon',
    'How these numbers are calculated' => 'Paano kinukuwenta ang mga numerong ito',
    'How this copy of B.E.S.T. Learning and Interactive Study System is configured. Secrets such as API keys and database passwords are never shown; change them in the server\'s .env file.' => 'Kung paano naka-configure ang kopyang ito ng B.E.S.T. Learning and Interactive Study System. Hindi kailanman ipinapakita ang mga lihim gaya ng API key at password ng database; baguhin ang mga ito sa .env file ng server.',
    'How this is calculated' => 'Paano ito kinukuwenta',
    'How this is graded' => 'Paano ito mamarkahan',
    'I can\'t help with that request. If you think this is a mistake, try asking in a different way, or ask your teacher.' => 'Hindi ako makatutulong sa kahilingang iyan. Kung sa tingin mo ay pagkakamali ito, subukang magtanong sa ibang paraan, o magtanong sa iyong guro.',
    'I have checked every line against the official order' => 'Nasuri ko ang bawat linya laban sa opisyal na kautusan',
