    'I will follow the rules for using B.E.S.T. Learning and Interactive Study System' => 'Susundin ko ang mga patakaran sa paggamit ng B.E.S.T. Learning and Interactive Study System',
    'I. Objectives' => 'I. Layunin',
    'II. Content' => 'II. Nilalaman',
    'III. Learning resources' => 'III. Kagamitang panturo',
    'IV. Procedures' => 'IV. Pamamaraan',
    'Ideas' => 'Mga ideya',
    'If an answer seems wrong or unsafe, use Report. Your report and that answer go to school administrators.' => 'Kung mukhang mali o hindi ligtas ang isang sagot, gamitin ang I-report. Mapupunta sa mga administrador ng paaralan ang iyong report at ang sagot na iyon.',
    'If something worries you' => 'Kung may ikinababahala ka',
    'If the companion helped you understand something you used in your work, say so when your teacher asks.' => 'Kung tinulungan ka ng companion na maunawaan ang isang bagay na ginamit mo sa iyong gawain, sabihin ito kapag nagtanong ang iyong guro.',
    'If the materials do not cover your question, the companion says so. Any general explanation is labelled as not coming from your class.' => 'Kung hindi saklaw ng mga materyal ang iyong tanong, sasabihin ito ng companion. May label ang anumang pangkalahatang paliwanag na nagsasabing hindi ito mula sa iyong klase.',
    'If you cannot use your phone, type one of these instead of a code from the app. Each works once. They are shown only now: print them or write them down, and keep them somewhere safe.' => 'Kung hindi mo magamit ang iyong phone, i-type ang isa sa mga ito sa halip na code mula sa app. Isang beses lang gumagana ang bawat isa. Ngayon lang ipinapakita ang mga ito: i-print o isulat, at itago sa ligtas na lugar.',
    'If you did not ask for this, tell your school\'s administrator.' => 'Kung hindi mo ito hiniling, sabihan ang administrador ng iyong paaralan.',
    'If you report a companion answer, that answer and your note are shown to administrators so they can look into it.' => 'Kapag nag-report ka ng sagot ng companion, ipapakita ang sagot na iyon at ang iyong tala sa mga administrador para masuri nila ito.',
    'If you were not expecting this email, you can ignore it.' => 'Kung hindi mo inaasahan ang email na ito, maaari mo itong balewalain.',
