    'Import your school\'s list from a spreadsheet. B.E.S.T. Learning and Interactive Study System does not come with codes of its own.' => 'I-import ang listahan ng iyong paaralan mula sa isang spreadsheet. Walang sariling mga code ang B.E.S.T. Learning and Interactive Study System.',
    'Important actions in your school: who did what, and when. Entries cannot be edited. Conversation text, passwords and keys are never recorded.' => 'Mahahalagang aksiyon sa iyong paaralan: sino ang gumawa ng ano, at kailan. Hindi mae-edit ang mga entry. Hindi kailanman itinatala ang teksto ng mga usapan, password at key.',
    'Imported :count people from CSV' => 'Nag-import ng :count tao mula sa CSV',
