    'In class or on paper' => 'Sa klase o sa papel',
    'In class or on paper. Students see the instructions and the date, never a form to submit. After class you type each student\'s score into a grid, mark who was absent, and release the scores when you are ready. You can print a blank copy and an answer key.' => 'Sa klase o sa papel. Nakikita ng mga mag-aaral ang mga tagubilin at ang petsa, hindi kailanman ng form na ipapasa. Pagkatapos ng klase, ita-type mo ang iskor ng bawat mag-aaral sa isang talaan, itatala kung sino ang lumiban, at ilalabas ang mga iskor kapag handa ka na. Makakapag-print ka ng blangkong kopya at susi sa pagwawasto.',
