    'Invitation links' => 'Mga link ng imbitasyon',
    'Invitation links and slips work once and expire after 14 days. Ask your teacher, adviser or school administrator for a new one.' => 'Isang beses lang gumagana ang mga link ng imbitasyon at slip at nag-e-expire pagkalipas ng 14 na araw. Humingi ng bago sa iyong guro, adviser o administrador ng paaralan.',
    'Invitation not yet accepted' => 'Hindi pa tinatanggap ang imbitasyon',
    'Invite people one at a time or import a CSV. B.E.S.T. Learning and Interactive Study System shows each invitation link for you to share; no email is sent unless an email service is configured.' => 'Mag-imbita ng mga tao nang isa-isa o mag-import ng CSV. Ipinapakita ng B.E.S.T. Learning and Interactive Study System ang bawat link ng imbitasyon para maibahagi mo; walang email na ipinapadala maliban kung may naka-configure na email service.',
    'Invite people one at a time or import a class list from a spreadsheet.' => 'Mag-imbita ng mga tao nang isa-isa o mag-import ng listahan ng klase mula sa spreadsheet.',
