    'Invited a :role' => 'Nag-imbita ng :role',
    'Inviting a whole section? Import a spreadsheet instead.' => 'Mag-iimbita ng buong seksiyon? Mag-import na lang ng spreadsheet.',
    'It can be wrong. Check what it says against your class materials and ask your teacher when unsure.' => 'Maaari itong magkamali. Ihambing ang sinasabi nito sa mga materyal ng iyong klase at magtanong sa iyong guro kapag hindi sigurado.',
    'It explains topics, asks you questions, makes flashcards and study plans, and shows which class material each point comes from.' => 'Nagpapaliwanag ito ng mga paksa, nagtatanong sa iyo, gumagawa ng flashcards at plano sa pag-aaral, at ipinapakita kung saang materyal ng klase galing ang bawat punto.',
    'It has no grading category, so its scores are not counted in the gradebook yet. Edit it to choose one.' => 'Wala itong kategorya ng pagmamarka, kaya hindi pa binibilang sa talaan ng grado ang mga iskor nito. I-edit ito para pumili ng isa.',
    'It is incorrect' => 'Mali ito',
