    'On for this student' => 'Naka-on para sa mag-aaral na ito',
    'On since :date' => 'Naka-on mula :date',
    'On time' => 'Nasa oras',
    'On: people with a B.E.S.T. Learning and Interactive Study System account on :domains can sign in with Google.' => 'Naka-on: makakapag-sign in gamit ang Google ang mga may account sa B.E.S.T. Learning and Interactive Study System sa :domains.',
    'Once work reaches its due date, completion and question results appear here.' => 'Kapag sumapit na ang takdang araw ng gawain, lalabas dito ang pagkumpleto at resulta ng mga tanong.',
    'One fictional school with teachers, students, classes, materials, assignments and feedback. No real people or records.' => 'Isang kathang-isip na paaralan na may mga guro, mag-aaral, klase, materyal, gawain at feedback. Walang tunay na tao o talaan.',
    'One or more usernames or emails, separated by spaces, commas or new lines.' => 'Isa o higit pang username o email, pinaghihiwalay ng espasyo, kuwit o bagong linya.',
    'One per line, in order.' => 'Isa bawat linya, nang sunud-sunod.',
    'One per line. Spacing and a final full stop are ignored. You can always adjust marks while grading.' => 'Isa bawat linya. Hindi pinapansin ang espasyo at tuldok sa dulo. Maaari mo pa ring ayusin ang marka habang nagmamarka.',
    'One question at a time and hints first, so you work it out yourself.' => 'Isang tanong sa bawat pagkakataon at pahiwatig muna, para ikaw mismo ang makaisip.',
    'One result has been released so far. The chart appears from the second result.' => 'Isang resulta pa lang ang nailalabas. Lalabas ang tsart simula sa ikalawang resulta.',
    'One row per line: the lowest initial grade of the row, then the grade to report, for example “60.00 75”. You can paste two columns from a spreadsheet or the ranges from the order, such as “60.00 – 61.59 75”.' => 'Isang hilera bawat linya: ang pinakamababang paunang grado ng hilera, saka ang gradong iuulat, halimbawa “60.00 75”. Maaari kang mag-paste ng dalawang hanay mula sa spreadsheet o ng mga saklaw mula sa kautusan, gaya ng “60.00 – 61.59 75”.',
    'One section of a subject in one period, for example “Science 9 – Narra”.' => 'Isang seksiyon ng isang asignatura sa isang panahong akademiko, halimbawa “Science 9 – Narra”.',
    'Online' => 'Online',
    'Online submissions' => 'Mga ipinasa online',
    'Online work due' => 'Online na gawaing dapat ipasa',
    'Online work due: each student and each assignment or quiz whose due date for that student (their own date if they have one) fell that week and has passed. Excused work and work done on paper are left out. Missing means not handed in yet.' => 'Online na gawaing dapat ipasa: bawat mag-aaral at bawat takdang-aralin o quiz na ang takdang araw para sa mag-aaral na iyon (ang sarili niyang petsa kung mayroon) ay pumatak sa linggong iyon at lumipas na. Hindi kasama ang pinalibreng gawain at gawaing ginawa sa papel. Ang hindi naipasa ay hindi pa naipapasa.',
    'Only :name' => ':name lamang',
    'Only a section without classes can be removed. Change the section of its classes first.' => 'Seksiyong walang klase lang ang maaaring alisin. Palitan muna ang seksiyon ng mga klase nito.',
    'Only a student\'s latest submitted quiz attempt can be reopened.' => 'Ang pinakahuling naipasang pagtatangka lamang sa quiz ng mag-aaral ang maaaring muling buksan.',
    'Only do this after reading every drafted question and its answer.' => 'Gawin lamang ito pagkatapos basahin ang bawat nabuong tanong at ang sagot nito.',
    'Only drafts that no student has started can be deleted. Archive it instead.' => 'Ang mga draft lamang na hindi pa sinisimulan ng sinumang mag-aaral ang maaaring burahin. I-archive na lang ito.',
    'Only existing accounts can sign in this way, found by their email; roles stay as they are here, and two-step sign-in still asks for its code. The README explains how to create the client in Google Cloud.' => 'Ang mga dati nang account lamang ang makakapag-sign in sa ganitong paraan, na hinahanap ayon sa kanilang email; nananatili ang mga tungkulin gaya ng nakatakda rito, at humihingi pa rin ng code ang dalawang-hakbang na pag-sign in. Ipinapaliwanag ng README kung paano gumawa ng client sa Google Cloud.',
    'Only for scheduled materials. Your timezone: :tz.' => 'Para lamang sa mga nakaiskedyul na materyal. Iyong timezone: :tz.',
    'Only submitted assignments can be returned.' => 'Ang mga naipasang gawain lamang ang maaaring ibalik.',
    'Only teachers of the class can see it.' => 'Ang mga guro lamang ng klase ang makakakita nito.',
    'Only the reported answer is shown here; the student\'s question and the rest of the conversation stay private.' => 'Ang ini-report na sagot lamang ang ipinapakita rito; nananatiling pribado ang tanong ng mag-aaral at ang iba pang bahagi ng usapan.',
    'Only used with “Accept with a penalty”.' => 'Ginagamit lamang kasama ng “Tanggapin nang may bawas”.',
    'Only when a student chooses to. Teachers never see conversations otherwise.' => 'Kapag pinili lamang ng mag-aaral. Kung hindi, hindi kailanman nakikita ng mga guro ang mga usapan.',
