    'Opens: :t' => 'Magbubukas: :t',
    'Optional and unique. Students without email sign in with their username.' => 'Opsiyonal at hindi puwedeng doble. Nagsa-sign in gamit ang username ang mga mag-aaral na walang email.',
    'Optional words shown next to grades, such as “Very satisfactory”. With transmutation on, they follow the transmuted grade.' => 'Mga opsiyonal na salitang ipinapakita sa tabi ng mga grado, gaya ng “Very satisfactory”. Kapag naka-on ang transmutasyon, sinusunod nila ang na-transmute na grado.',
    'Optional, students only. Your list: :grades.' => 'Opsiyonal, para sa mga mag-aaral lamang. Iyong listahan: :grades.',
    'Optional. JPG or PNG up to 2 MB. Location and camera details are removed.' => 'Opsiyonal. JPG o PNG hanggang 2 MB. Inaalis ang mga detalye ng lokasyon at camera.',
    'Optional. Leave empty and B.E.S.T. Learning and Interactive Study System makes one from the name, such as juan.delacruz.' => 'Opsiyonal. Iwanang blangko at gagawa ang B.E.S.T. Learning and Interactive Study System mula sa pangalan, gaya ng juan.delacruz.',
    'Optional. Questions here are printed on the blank copy and the answer key; students do not answer them online.' => 'Opsiyonal. Ang mga tanong dito ay ipi-print sa blangkong kopya at sa susi sa pagwawasto; hindi ito sinasagutan ng mga mag-aaral online.',
    'Optional. Shown instead of your first name, for example a nickname.' => 'Opsiyonal. Ipapakita sa halip na iyong unang pangalan, halimbawa ang iyong palayaw.',
    'Optional. Teachers usually have one; students without email sign in with their username.' => 'Opsiyonal. Karaniwang may email ang mga guro; nagsa-sign in gamit ang username ang mga mag-aaral na walang email.',
    'Optional. The exact name of an active class, to enrol the person.' => 'Opsiyonal. Ang eksaktong pangalan ng isang aktibong klase, para maitala roon ang tao.',
    'Optional. You can add classes later.' => 'Opsiyonal. Maaari kang magdagdag ng mga klase mamaya.',
    'Optional; sets the points and guides marking.' => 'Opsiyonal; itinatakda nito ang puntos at gumagabay sa pagmamarka.',
    'Optional; used when marking essay answers.' => 'Opsiyonal; ginagamit sa pagmamarka ng mga sagot na sanaysay.',
    'Or add by username or email' => 'O magdagdag gamit ang username o email',
    'Other' => 'Iba pa',
