    'Other comments' => 'Iba pang komento',
    'Other materials' => 'Iba pang materyal',
    'Other pages, quizzes and the companion need a connection. Without one, B.E.S.T. Learning and Interactive Study System says so and lists the files kept on that device.' => 'Kailangan ng koneksiyon ang ibang pahina, ang mga quiz at ang companion. Kapag walang koneksiyon, sinasabi ito ng B.E.S.T. Learning and Interactive Study System at inililista ang mga file na nakatago sa device na iyon.',
    'Out of :n points.' => 'Mula sa :n puntos.',
    'Outcome' => 'Kinalabasan',
    'Outline a lesson from your objectives and approved materials.' => 'Bumuo ng balangkas ng aralin mula sa iyong mga layunin at aprubadong materyal.',
