    'PDF reading is not installed on this server. An administrator needs to run composer install.' => 'Hindi naka-install sa server na ito ang pagbasa ng PDF. Kailangang patakbuhin ng isang administrador ang composer install.',
    'PDF, DOCX, PPTX, TXT or MD, up to :mb MB.' => 'PDF, DOCX, PPTX, TXT o MD, hanggang :mb MB.',
    'PDF, Word, PowerPoint, text and images, up to 5 files.' => 'PDF, Word, PowerPoint, teksto at larawan, hanggang 5 file.',
    'PDF, Word, PowerPoint, text or Markdown files are read so the companion can quote them with page references. Scanned pages without real text cannot be read.' => 'Binabasa ang mga PDF, Word, PowerPoint, text o Markdown na file para masipi ito ng companion nang may numero ng pahina. Hindi mababasa ang mga na-scan na pahinang walang tunay na teksto.',
    'PDF, Word, PowerPoint, text, JPG or PNG. Up to 5 files, :mb MB each.' => 'PDF, Word, PowerPoint, teksto, JPG o PNG. Hanggang 5 file, :mb MB bawat isa.',
    'PNG or JPG, up to 1 MB. A square image works best. Shown beside the school name.' => 'PNG o JPG, hanggang 1 MB. Pinakamainam ang parisukat na larawan. Ipinapakita sa tabi ng pangalan ng paaralan.',
