    'Password changed. Other devices have been signed out.' => 'Napalitan ang password. Na-sign out na ang ibang device.',
    'Password links and slips work once and expire after 48 hours. Ask your teacher, adviser or school administrator for a new one.' => 'Isang beses lang gumagana ang mga link at slip sa password at nag-e-expire pagkalipas ng 48 oras. Humingi ng bago sa iyong guro, adviser o administrador ng paaralan.',
    'Password reset link for :name' => 'Link sa pag-reset ng password para kay :name',
    'Password slip' => 'Slip sa password',
    'Pending invitations, privacy requests, reported answers, new feedback and failed uploads appear here.' => 'Lumalabas dito ang mga nakabinbing imbitasyon, kahilingan sa privacy, ini-report na sagot, bagong feedback at mga nabigong upload.',
    'People' => 'Mga tao',
    'People can choose their own language in their settings.' => 'Maaaring piliin ng bawat tao ang sarili niyang wika sa kanyang mga setting.',
    'People you choose read and accept the privacy notice and the rules for using B.E.S.T. Learning and Interactive Study System when they first sign in and again whenever either changes. B.E.S.T. Learning and Interactive Study System records who accepted which version and when.' => 'Binabasa at tinatanggap ng mga taong pipiliin mo ang abiso sa privacy at ang mga patakaran sa paggamit ng B.E.S.T. Learning and Interactive Study System sa una nilang pag-sign in at muli tuwing magbabago ang alinman sa mga ito. Itinatala ng B.E.S.T. Learning and Interactive Study System kung sino ang tumanggap, kung aling bersiyon at kailan.',
