    'Plan lessons from scratch or from an AI draft based on your materials. Students see a lesson only after you publish it.' => 'Magplano ng aralin mula sa simula o mula sa draft ng AI na batay sa iyong mga materyal. Makikita lamang ng mga mag-aaral ang aralin pagkatapos mo itong i-publish.',
    'Plan short study sessions on the calendar, or ask the companion to help you make a plan.' => 'Magplano ng maiikling sesyon ng pag-aaral sa kalendaryo, o hilingin sa companion na tulungan kang gumawa ng plano.',
