    'Prints a sign-in slip with a new one-time code for the :count student who has not set up an account yet. Earlier links for them stop working.' => 'Magpi-print ng slip sa pag-sign in na may bagong isang beses na code para sa :count mag-aaral na hindi pa nakapag-set up ng account. Titigil sa paggana ang mga naunang link niya.',
