    'Shown to students in the companion, telling them where to get help from a person.' => 'Ipinapakita sa mga mag-aaral sa companion, para sabihin kung saan sila makahihingi ng tulong sa isang tao.',
    'Shown when your teacher releases it.' => 'Ipinapakita kapag inilabas na ng iyong guro.',
    'B.E.S.T. Learning and Interactive Study System (automatic)' => 'B.E.S.T. Learning and Interactive Study System (awtomatiko)',
    'B.E.S.T. Learning and Interactive Study System builds a JSON file with their account, classes, submitted work, released grades, companion conversations, practice and study plans. Only the requester can download it, for :days days.' => 'Bubuo ang B.E.S.T. Learning and Interactive Study System ng JSON file na naglalaman ng kanyang account, mga klase, naipasang gawain, mga inilabas na grado, mga usapan sa companion, pagsasanay at mga plano sa pag-aaral. Ang humiling lamang ang makapagda-download nito, sa loob ng :days araw.',
    'B.E.S.T. Learning and Interactive Study System can\'t reach the AI service right now. Try again in a few minutes. Everything else in B.E.S.T. Learning and Interactive Study System works as usual.' => 'Hindi maabot ng B.E.S.T. Learning and Interactive Study System ang AI service ngayon. Subukang muli pagkalipas ng ilang minuto. Gumagana pa rin nang normal ang lahat ng iba pa sa B.E.S.T. Learning and Interactive Study System.',
    'B.E.S.T. Learning and Interactive Study System cannot reach its database right now. An administrator needs to check the configuration.' => 'Hindi maabot ng B.E.S.T. Learning and Interactive Study System ang database nito ngayon. Kailangang suriin ng isang administrador ang configuration.',
    'B.E.S.T. Learning and Interactive Study System could not email this link to :address. Copy it now and send it through your school\'s usual channel; it will not be shown again.' => 'Hindi ma-email ng B.E.S.T. Learning and Interactive Study System ang link na ito sa :address. Kopyahin ito ngayon at ipadala sa karaniwang paraan ng iyong paaralan; hindi na ito ipapakitang muli.',
    'B.E.S.T. Learning and Interactive Study System creates the account and a private invitation link or a printed sign-in slip. The person sets their own password.' => 'Gagawa ang B.E.S.T. Learning and Interactive Study System ng account at ng pribadong link ng imbitasyon o naka-print na slip sa pag-sign in. Ang tao mismo ang magtatakda ng kanyang password.',
    'B.E.S.T. Learning and Interactive Study System drafts questions from the materials you choose. Every drafted question waits for your review and cannot be published until you approve it.' => 'Bumubuo ang B.E.S.T. Learning and Interactive Study System ng mga tanong mula sa mga materyal na pipiliin mo. Naghihintay ng iyong pagsusuri ang bawat nabuong tanong at hindi ito mapa-publish hangga\'t hindi mo inaaprubahan.',
    'B.E.S.T. Learning and Interactive Study System emailed this link to :address. If it does not arrive, copy the link now and send it through your school\'s usual channel; it will not be shown again.' => 'In-email ng B.E.S.T. Learning and Interactive Study System ang link na ito sa :address. Kung hindi ito dumating, kopyahin ang link ngayon at ipadala sa karaniwang paraan ng iyong paaralan; hindi na ito ipapakitang muli.',
    'B.E.S.T. Learning and Interactive Study System is currently in demo mode: no AI service is connected, and nothing you type leaves the school\'s server. Answers are built from passages of your class materials.' => 'Kasalukuyang naka-demo mode ang B.E.S.T. Learning and Interactive Study System: walang nakakonektang AI service, at walang anumang tinitipa mo ang lumalabas sa server ng paaralan. Binubuo ang mga sagot mula sa mga sipi ng mga materyal ng iyong klase.',
    'B.E.S.T. Learning and Interactive Study System is not available right now' => 'Hindi magagamit ang B.E.S.T. Learning and Interactive Study System ngayon',
    'B.E.S.T. Learning and Interactive Study System needs a connection to open this page. Check your mobile data or Wi-Fi, then try again.' => 'Kailangan ng B.E.S.T. Learning and Interactive Study System ng koneksiyon para mabuksan ang pahinang ito. Tingnan ang iyong mobile data o Wi-Fi, saka subukang muli.',
    'B.E.S.T. Learning and Interactive Study System records which version you accepted and when.' => 'Itinatala ng B.E.S.T. Learning and Interactive Study System kung aling bersiyon ang tinanggap mo at kailan.',
    'B.E.S.T. Learning and Interactive Study System shows you a private link that works once and expires in :days days. You can print it as a sign-in slip instead.' => 'Ipapakita sa iyo ng B.E.S.T. Learning and Interactive Study System ang isang pribadong link na isang beses lang gumagana at mag-e-expire sa loob ng :days araw. Puwede mo rin itong i-print bilang slip sa pag-sign in.',
