    'Someone at school is checking it.' => 'May tumitingin na rito sa paaralan.',
    'Someone who already has an account is recognised by email or username, or else by the same name, role and grade level. Imported people get one-time codes you print on sign-in slips or share as links.' => 'Nakikilala ang may account na sa pamamagitan ng email o username, o kaya ng parehong pangalan, tungkulin at baitang. Ang mga na-import ay may isang beses na code na ipi-print mo sa mga slip sa pag-sign in o ibabahagi bilang link.',
