    'Students are notified in B.E.S.T. Learning and Interactive Study System.' => 'Inaabisuhan ang mga mag-aaral sa B.E.S.T. Learning and Interactive Study System.',
    'Students can also attach up to 5 files.' => 'Maaari ring maglakip ang mga mag-aaral ng hanggang 5 file.',
    'Students can choose to share a single companion answer, with a note, so you can see what they are working through. You never see the rest of their conversations.' => 'Maaaring piliin ng mga mag-aaral na magbahagi ng isang sagot ng companion, kasama ang isang tala, para makita mo kung ano ang pinag-aaralan nila. Hindi mo kailanman makikita ang iba pang bahagi ng kanilang mga usapan.',
    'Students can delete their conversations' => 'Maaaring burahin ng mga mag-aaral ang kanilang mga usapan',
    'Students can share an excerpt with their teacher' => 'Maaaring magbahagi ng sipi ang mga mag-aaral sa kanilang guro',
    'Students can then ask questions about it and get answers that quote it, once it is released.' => 'Kapag nailabas na ito, makapagtatanong ang mga mag-aaral tungkol dito at makakakuha ng mga sagot na sumisipi rito.',
    'Students chose to share these with you. Open the class to read them.' => 'Pinili ng mga mag-aaral na ibahagi ang mga ito sa iyo. Buksan ang klase para mabasa ang mga ito.',
    'Students enter it on their Classes page. Expires :date.' => 'Inilalagay ito ng mga mag-aaral sa kanilang pahina ng Mga klase. Mag-e-expire sa :date.',
    'Students have already started this work, so its questions are locked. Duplicate it to make a changed version.' => 'Nasimulan na ng mga mag-aaral ang gawaing ito, kaya naka-lock ang mga tanong nito. Gumawa ng kopya nito para makagawa ng binagong bersiyon.',
    'Students have started this work, so changing questions would make attempts unfair. You can still change dates and instructions, or duplicate it to make a new version.' => 'Nasimulan na ng mga mag-aaral ang gawaing ito, kaya magiging hindi patas ang mga pagtatangka kung babaguhin ang mga tanong. Maaari mo pa ring baguhin ang mga petsa at tagubilin, o gumawa ng kopya nito para sa bagong bersiyon.',
    'Students in :class' => 'Mga mag-aaral sa :class',
    'Students in :class will see it and get a notification.' => 'Makikita ito ng mga mag-aaral sa :class at makatatanggap sila ng abiso.',
    'Students in :class will see it now and get a notification.' => 'Makikita na ito ngayon ng mga mag-aaral sa :class at makatatanggap sila ng abiso.',
    'Students in :class will see this lesson and get a notification.' => 'Makikita ng mga mag-aaral sa :class ang araling ito at makatatanggap sila ng abiso.',
    'Students in :section' => 'Mga mag-aaral sa :section',
    'Students in green and white uniforms gather in the school\'s covered court as a speaker addresses them from the podium.' => 'Nagtitipon sa covered court ng paaralan ang mga mag-aaral na nakaunipormeng berde at puti habang may nagsasalita sa kanila mula sa podium.',
    'Students must accept them' => 'Kailangang tanggapin ng mga mag-aaral',
    'Students not in this class' => 'Mga mag-aaral na wala sa klaseng ito',
    'Students only.' => 'Para sa mga mag-aaral lamang.',
    'Students practising' => 'Mga mag-aaral na nagsasanay',
    'Students see grades only after you release them.' => 'Makikita lamang ng mga mag-aaral ang grado pagkatapos mo itong ilabas.',
    'Students see it' => 'Nakikita ng mga mag-aaral',
    'Students see links to these materials once the materials are released.' => 'Makikita ng mga mag-aaral ang mga link sa mga materyal na ito kapag nailabas na ang mga materyal.',
    'Students type a code to join a class. Turning this off disables every current code.' => 'Nagta-type ang mga mag-aaral ng code para sumali sa klase. Kapag in-off ito, hindi na gagana ang lahat ng kasalukuyang code.',
    'Students using the companion' => 'Mga mag-aaral na gumagamit ng companion',
    'Students who submitted will be able to see the correct answers and explanations now.' => 'Makikita na ngayon ng mga mag-aaral na nakapagpasa ang mga tamang sagot at paliwanag.',
    'Students will no longer be able to submit or start attempts.' => 'Hindi na makakapagpasa o makapagsisimula ng pagtatangka ang mga mag-aaral.',
    'Students will no longer see it. Released grades stay on record.' => 'Hindi na ito makikita ng mga mag-aaral. Mananatiling nakatala ang mga gradong nailabas na.',
    'Students will no longer see this announcement.' => 'Hindi na makikita ng mga mag-aaral ang anunsiyong ito.',
    'Students will no longer see this lesson.' => 'Hindi na makikita ng mga mag-aaral ang araling ito.',
    'Students will see it from the opening date and be notified now.' => 'Makikita ito ng mga mag-aaral simula sa petsa ng pagbubukas at aabisuhan sila ngayon.',
    'Students will see the updated version.' => 'Makikita ng mga mag-aaral ang na-update na bersiyon.',
    'Students with :n or more pieces of work missing or handed in late among those due in the last :days days, by name. Each student\'s own due dates count, and excused work is left out.' => 'Mga mag-aaral na may :n o higit pang gawaing hindi naipasa o huling naipasa sa mga takda sa nakaraang :days araw, ayon sa pangalan. Ginagamit ang sariling takdang araw ng bawat mag-aaral, at hindi isinasama ang mga pinalibreng gawain.',
    'Students\' companion answers can quote this material now.' => 'Maaari nang sipiin ng companion ang materyal na ito sa mga sagot nito sa mga mag-aaral.',
    'Students\' companion conversations are private. There is no tool to read them, and none should be asked for.' => 'Pribado ang mga usapan ng mga mag-aaral sa companion. Walang kagamitan para basahin ang mga ito, at hindi dapat humingi nito.',
    'Students\' review of missed questions' => 'Pagbabalik-aral ng mga mag-aaral sa mga tanong na hindi nakuha',
    'Study plans' => 'Mga plano sa pag-aaral',
    'Study session added.' => 'Naidagdag ang sesyon ng pag-aaral.',
    'Study session removed.' => 'Inalis ang sesyon ng pag-aaral.',
    'Study tools and updates' => 'Mga kagamitan sa pag-aaral at update',
    'Subject' => 'Asignatura',
    'Subject added.' => 'Naidagdag ang asignatura.',
    'Subject groups' => 'Mga pangkat ng asignatura',
    'Subject groups and their weights' => 'Mga pangkat ng asignatura at ang timbang nila',
    'Subject groups need weighted categories. Choose “Weighted categories” above first.' => 'Kailangan ng mga pangkat ng asignatura ang mga kategoryang may timbang. Piliin muna ang “Mga kategoryang may timbang” sa itaas.',
    'Subject groups saved. Gradebooks use their weights right away.' => 'Na-save ang mga pangkat ng asignatura. Agad gagamitin ng mga talaan ng grado ang timbang nila.',
    'Subject matter' => 'Paksang-aralin',
    'Subject name' => 'Pangalan ng asignatura',
    'Subject saved.' => 'Na-save ang asignatura.',
    'Subjects' => 'Mga asignatura',
    'Subjects and terms' => 'Mga asignatura at termino',
    'Subjects group classes across sections. Archived subjects stay on existing classes but cannot be used for new ones.' => 'Pinagsasama-sama ng mga asignatura ang mga klase sa iba\'t ibang seksiyon. Nananatili sa mga dating klase ang mga naka-archive na asignatura pero hindi na magagamit sa mga bago.',
    'Submission receipt' => 'Resibo ng pagpasa',
    'Submissions' => 'Mga ipinasa',
    'Submissions and grading' => 'Pagpasa at pagmamarka',
    'Submissions for :title' => 'Mga ipinasa para sa :title',
    'Submissions, AI drafts awaiting your review, and processing problems will show up here.' => 'Lalabas dito ang mga ipinasang gawain, mga draft ng AI na naghihintay ng iyong pagsusuri, at mga problema sa pagproseso.',
    'Submissions: :title' => 'Mga ipinasa: :title',
    'Submit' => 'Ipasa',
    'Submit again' => 'Ipasang muli',
    'Submit assignment' => 'Ipasa ang gawain',
    'Submit quiz' => 'Ipasa ang quiz',
    'Submit this quiz?' => 'Ipasa ang quiz na ito?',
    'Submit your work?' => 'Ipasa ang iyong gawa?',
    'Submitted' => 'Naipasa',
    'Submitted :when' => 'Naipasa :when',
    'Submitted a privacy request' => 'Nagpadala ng kahilingan sa privacy',
    'Submitted a quiz' => 'Nagpasa ng quiz',
    'Submitted attempts' => 'Mga naipasang pagtatangka',
    'Submitted by the student' => 'Ipinasa ng mag-aaral',
    'Submitted late' => 'Naipasa nang huli',
    'Submitted. Your receipt code is :code.' => 'Naipasa. Ang code ng iyong resibo ay :code.',
    'Submitting…' => 'Ipinapasa…',
    'Suggest reteaching ideas' => 'Magmungkahi ng mga ideya sa muling pagtuturo',
    'Suggest scores' => 'Magmungkahi ng iskor',
    'Suggested :when by :model. It is advice only; the grade is yours.' => 'Iminungkahi :when ng :model. Payo lamang ito; ikaw ang magpapasya ng grado.',
    'Suggestion copied into the form. Check it, then save.' => 'Nakopya ang mungkahi sa form. Suriin ito, saka i-save.',
    'Suggestion ready. Review it; nothing changes until you save.' => 'Handa na ang mungkahi. Suriin ito; walang magbabago hangga\'t hindi ka nagse-save.',
    'Suggestions for you to judge. They are based only on the topic totals above, never on individual students.' => 'Mga mungkahing ikaw ang huhusga. Nakabatay lamang ang mga ito sa kabuuang resulta bawat paksa sa itaas, hindi kailanman sa mga indibidwal na mag-aaral.',
    'Summarize my material' => 'Ibuod ang aking materyal',
    'Summary' => 'Buod',
    'Switch off' => 'I-off',
    'Switch off two-step sign-in' => 'I-off ang dalawang-hakbang na pag-sign in',
    'Switch off two-step sign-in?' => 'I-off ang dalawang-hakbang na pag-sign in?',
    'Switched off for your account by your school' => 'Ini-off ng iyong paaralan para sa iyong account',
    'Switched off two-step sign-in for someone' => 'Ini-off ang dalawang-hakbang na pag-sign in ng isang tao',
    'Switched the AI companion off for a student' => 'Ini-off ang AI companion para sa isang mag-aaral',
    'Switched the AI companion on for a student' => 'Ini-on ang AI companion para sa isang mag-aaral',
    'Switched the transmutation table on' => 'Pinagana ang talahanayan ng transmutasyon',
    'System checks' => 'Mga pagsusuri ng sistema',
    'Table' => 'Talahanayan',
    'Table saved and switched on. Grading periods now report transmuted grades.' => 'Na-save at pinagana ang talahanayan. Na-transmute na grado na ngayon ang iniuulat ng mga panahon ng pagmamarka.',
    'Table saved. It is not used until it is checked and switched on.' => 'Na-save ang talahanayan. Hindi ito gagamitin hangga\'t hindi ito nasusuri at napapagana.',
    'Teacher' => 'Guro',
    'Teacher comments' => 'Mga komento ng guro',
    'Teacher to be assigned' => 'Itatalaga pa ang guro',
    'Teacher:' => 'Guro:',
    'Teachers' => 'Mga guro',
    'Teachers and administrators must accept them too' => 'Kailangan din itong tanggapin ng mga guro at administrador',
    'Teachers and students keep read access, but no new work, materials or members can be added. You can restore it later.' => 'Makababasa pa rin ang mga guro at mag-aaral, pero wala nang maidaragdag na bagong gawain, materyal o miyembro. Maaari mo itong ibalik sa ibang pagkakataon.',
    'Teachers can create class codes' => 'Maaaring gumawa ng class code ang mga guro',
    'Teachers can use AI drafting tools' => 'Maaaring gumamit ang mga guro ng mga AI tool sa pagbuo ng draft',
    'Teaching dates and time' => 'Petsa at oras ng pagtuturo',
    'Tell the student what to change (up to 2,000 characters).' => 'Sabihin sa mag-aaral kung ano ang babaguhin (hanggang 2,000 character).',
    'Tell your school when something in B.E.S.T. Learning and Interactive Study System is not working or is confusing, or share an idea. Your school\'s administrators read every message and may reply. It is not a chat, and it is not watched all the time.' => 'Sabihin sa iyong paaralan kapag may hindi gumagana o nakalilito sa B.E.S.T. Learning and Interactive Study System, o magbahagi ng ideya. Binabasa ng mga administrador ng iyong paaralan ang bawat mensahe at maaari silang tumugon. Hindi ito chat, at hindi ito binabantayan sa lahat ng oras.',
    'Template loaded, with :count grading period. Check its dates, the weights and the table against the order before teachers rely on them.' => 'Na-load ang template, may :count panahon ng pagmamarka. Suriin ang mga petsa nito, ang mga timbang at ang talahanayan laban sa kautusan bago ito asahan ng mga guro.',
    'Template loaded, with :count grading periods. Check their dates, the weights and the table against the order before teachers rely on them.' => 'Na-load ang template, may :count panahon ng pagmamarka. Suriin ang mga petsa ng mga ito, ang mga timbang at ang talahanayan laban sa kautusan bago ito asahan ng mga guro.',
    'Template loaded. Check the weights and the table against your school\'s policy before teachers rely on them.' => 'Na-load ang template. Suriin ang mga timbang at ang talahanayan batay sa patakaran ng iyong paaralan bago ito asahan ng mga guro.',
    'Templates' => 'Mga template',
    'Term' => 'Termino',
    'Test email sent to :address. Check that it arrived, and look in the spam folder too.' => 'Naipadala ang pansubok na email sa :address. Tingnan kung dumating ito, at silipin din ang spam folder.',
    'Text selected. Press Ctrl+C to copy.' => 'Napili ang teksto. Pindutin ang Ctrl+C para kopyahin.',
    'Text the companion can read' => 'Tekstong mababasa ng companion',
    'Thank you for helping keep the companion accurate and safe.' => 'Salamat sa pagtulong na mapanatiling tumpak at ligtas ang companion.',
    'Thank you. You can use B.E.S.T. Learning and Interactive Study System now.' => 'Salamat. Magagamit mo na ang B.E.S.T. Learning and Interactive Study System.',
    'Thank you. Your report was sent to the school administrators.' => 'Salamat. Naipadala ang iyong report sa mga administrador ng paaralan.',
    'Thank you. Your school\'s administrators will read it.' => 'Salamat. Babasahin ito ng mga administrador ng iyong paaralan.',
    'That Google sign-in did not start here or took too long. Try again.' => 'Hindi rito nagsimula ang pag-sign in gamit ang Google o masyadong natagalan ito. Subukang muli.',
    'That account is deactivated. Ask your school administrator.' => 'Na-deactivate na ang account na iyan. Magtanong sa administrador ng paaralan.',
    'That action is not available here' => 'Hindi magagamit dito ang aksiyong iyan',
    'That class is archived.' => 'Naka-archive ang klaseng iyan.',
    'That code does not match. Check that the phone sets its time automatically, then type the code the app shows now.' => 'Hindi tugma ang code na iyan. Tiyaking awtomatikong itinatakda ng phone ang oras nito, saka i-type ang code na ipinapakita ngayon ng app.',
    'That code does not match. Type the 6 digits your app shows now, or one of your recovery codes.' => 'Hindi tugma ang code na iyan. I-type ang 6 na numerong ipinapakita ngayon ng iyong app, o ang isa sa iyong mga recovery code.',
    'That code does not work. It may be mistyped, already used or expired. Check it, or ask your teacher or adviser for a new slip.' => 'Hindi gumagana ang code na iyan. Maaaring mali ang pagkaka-type, nagamit na, o expired na. Suriin ito, o humingi ng bagong slip sa iyong guro o adviser.',
    'That code is not valid or has expired. Check it with your teacher.' => 'Hindi wasto o nag-expire na ang code na iyan. Itanong ito sa iyong guro.',
    'That demo account is not available. Reload the demo data from the setup page.' => 'Hindi magagamit ang demo account na iyan. I-reload ang demo data mula sa setup page.',
    'That image could not be read. Try saving it again as a JPG or PNG.' => 'Hindi mabasa ang larawang iyan. Subukang i-save itong muli bilang JPG o PNG.',
    'That image could not be read. Try saving it again as a PNG or JPG.' => 'Hindi mabasa ang larawang iyan. Subukang i-save itong muli bilang PNG o JPG.',
    'That is a lot of requests in one minute. Wait a moment, then try again.' => 'Masyadong maraming kahilingan sa loob ng isang minuto. Maghintay sandali, saka subukang muli.',
    'That is not your current password.' => 'Hindi iyan ang iyong kasalukuyang password.',
    'That material is not available to the companion.' => 'Hindi magagamit ng companion ang materyal na iyan.',
    'That password is too easy to guess. Try a short phrase of a few words.' => 'Masyadong madaling hulaan ang password na iyan. Subukan ang maikling pariralang may ilang salita.',
    'That request was too large for the AI service. Try a shorter question or a smaller material.' => 'Masyadong malaki ang kahilingang iyan para sa AI service. Subukan ang mas maikling tanong o mas maliit na materyal.',
    'That upload is larger than the server allows (:max MB). Choose a smaller file.' => 'Mas malaki ang upload kaysa pinapayagan ng server (:max MB). Pumili ng mas maliit na file.',
    'The :n-minute timer starts now and keeps running even if you close the page.' => 'Magsisimula na ngayon ang :n minutong timer at tuloy-tuloy itong tatakbo kahit isara mo ang pahina.',
    'The AI service could not process this request.' => 'Hindi maproseso ng AI service ang kahilingang ito.',
    'The AI service declined this request. Try rephrasing it.' => 'Tinanggihan ng AI service ang kahilingang ito. Subukang sabihin ito sa ibang paraan.',
    'The AI service had a problem. Try again in a moment.' => 'Nagkaproblema ang AI service. Subukang muli mamaya.',
    'The AI service is busy right now. Try again in a minute.' => 'Abala ang AI service ngayon. Subukang muli pagkalipas ng isang minuto.',
    'The AI service is taking too long to answer. Try again in a few minutes. Everything else in B.E.S.T. Learning and Interactive Study System works as usual.' => 'Masyadong natatagalan ang AI service sa pagsagot. Subukang muli pagkalipas ng ilang minuto. Gumagana pa rin nang normal ang lahat ng iba pa sa B.E.S.T. Learning and Interactive Study System.',
    'The AI service is not set up yet: an administrator needs to add AI_API_KEY to the server configuration.' => 'Hindi pa naka-set up ang AI service: kailangang idagdag ng isang administrador ang AI_API_KEY sa configuration ng server.',
    'The AI service is not set up yet: an administrator needs to set AI_BASE_URL and AI_MODEL.' => 'Hindi pa naka-set up ang AI service: kailangang itakda ng isang administrador ang AI_BASE_URL at AI_MODEL.',
    'The AI service is overloaded at the moment. Try again shortly.' => 'Sobrang dami ng gumagamit sa AI service sa ngayon. Subukang muli maya-maya.',
    'The AI service returned something B.E.S.T. Learning and Interactive Study System could not read. Try again.' => 'May ibinalik ang AI service na hindi mabasa ng B.E.S.T. Learning and Interactive Study System. Subukang muli.',
    'The AI service sent an unreadable response. Try again.' => 'Nagpadala ang AI service ng sagot na hindi mabasa. Subukang muli.',
    'The PHP curl extension is required to reach the AI service.' => 'Kailangan ang PHP curl extension para maabot ang AI service.',
    'The answer is no longer available.' => 'Wala na ang sagot.',
    'The answer was acceptable on review.' => 'Katanggap-tanggap ang sagot nang suriin.',
    'The answer was interrupted. Try again.' => 'Naputol ang sagot. Subukang muli.',
    'The answer you reported was reviewed' => 'Nasuri na ang sagot na ini-report mo',
    'The answer: :answer' => 'Ang sagot: :answer',
    'The average uses only results your teachers have released, each as a percentage of its points, with every piece of work counting equally. Your class grade below can differ because your school may weight categories of work differently.' => 'Ginagamit lamang ng karaniwan ang mga resultang inilabas ng iyong mga guro, bawat isa bilang porsiyento ng puntos nito, at pantay ang bilang ng bawat gawain. Maaaring iba ang iyong grado sa klase sa ibaba dahil maaaring magkakaiba ang timbang na ibinibigay ng iyong paaralan sa bawat kategorya ng gawain.',
    'The bars cover your released work from the whole year.' => 'Saklaw ng mga bar ang iyong mga inilabas na gawain sa buong taon.',
    'The best attempt counts.' => 'Ang pinakamahusay na pagtatangka ang bibilangin.',
    'The chart appears once two or more results have been released.' => 'Lalabas ang tsart kapag dalawa o higit pang resulta na ang nailabas.',
    'The class code is turned off. Students can no longer use it.' => 'Naka-off na ang class code. Hindi na ito magagamit ng mga mag-aaral.',
    'The classes your school has assigned to you. Administrators create classes and assign teachers.' => 'Ang mga klaseng itinalaga sa iyo ng iyong paaralan. Ang mga administrador ang gumagawa ng mga klase at nagtatalaga ng mga guro.',
    'The code can have letters, numbers and . _ - / ( ), up to 60 characters' => 'Maaaring may mga titik, numero at . _ - / ( ) ang code, hanggang 60 karakter',
    'The companion and AI practice are available to this student.' => 'Magagamit ng mag-aaral na ito ang companion at ang AI na pagsasanay.',
    'The companion and AI practice are hidden for this student, and nothing about them is sent to an AI service.' => 'Nakatago ang companion at ang AI na pagsasanay para sa mag-aaral na ito, at walang anumang tungkol sa kanya ang ipinapadala sa AI service.',
    'The companion and AI practice are off for :name.' => 'Naka-off ang companion at ang AI na pagsasanay para kay :name.',
    'The companion and AI practice are on for :name.' => 'Naka-on ang companion at ang AI na pagsasanay para kay :name.',
    'The companion and AI practice are switched off for your account. Everything else in B.E.S.T. Learning and Interactive Study System works as usual. Ask your adviser if you have questions.' => 'Naka-off ang companion at ang AI na pagsasanay para sa iyong account. Gumagana gaya ng dati ang lahat ng iba pa sa B.E.S.T. Learning and Interactive Study System. Magtanong sa iyong adviser kung may tanong ka.',
    'The companion breaks a test into sessions students can add to their calendar.' => 'Hinahati ng companion ang paghahanda sa pagsusulit sa mga sesyon na maidaragdag ng mga mag-aaral sa kanilang kalendaryo.',
    'The companion can cite this' => 'Masisipi ito ng companion',
    'The companion can explain the topic or guide you with hints. It will not do the work for you.' => 'Maipapaliwanag ng companion ang paksa o magagabayan ka nito gamit ang mga pahiwatig. Hindi nito gagawin ang gawain para sa iyo.',
    'The companion will use it from the release date.' => 'Gagamitin ito ng companion simula sa petsa ng paglalabas.',
    'The companion will use it only after you publish it.' => 'Gagamitin lamang ito ng companion pagkatapos mo itong i-publish.',
    'The connection was lost. Check your internet connection and try again.' => 'Naputol ang koneksiyon. Suriin ang iyong koneksiyon sa internet at subukang muli.',
    'The core teaching. Citations like [1] refer to the sources listed on the right.' => 'Ang pangunahing pagtuturo. Ang mga pagbanggit gaya ng [1] ay tumutukoy sa mga sangguniang nakalista sa kanan.',
    'The current code will stop working immediately.' => 'Agad na titigil sa paggana ang kasalukuyang code.',
    'The database ":name" does not exist yet. B.E.S.T. Learning and Interactive Study System can create it with the account in .env.' => 'Wala pa ang database na ":name". Magagawa ito ng B.E.S.T. Learning and Interactive Study System gamit ang account sa .env.',
    'The database tables were already up to date.' => 'Napapanahon na ang mga table ng database.',
    'The dates must fall within :period (:from to :to).' => 'Dapat nasa loob ng :period ang mga petsa (:from hanggang :to).',
    'The dates overlap :name.' => 'Nagsasapawan ang mga petsa at ang :name.',
    'The demo data could not be loaded: :error' => 'Hindi ma-load ang demo data: :error',
    'The demo school was reset to its starting state.' => 'Naibalik sa panimulang kalagayan ang demo na paaralan.',
    'The description is longer than 1,000 characters' => 'Mas mahaba sa 1,000 karakter ang paglalarawan',
    'The document could not be opened. Save it again and re-upload.' => 'Hindi mabuksan ang dokumento. I-save itong muli at i-upload ulit.',
    'The document is missing its main text part.' => 'Nawawala sa dokumento ang pangunahing bahagi ng teksto nito.',
    'The document structure could not be read.' => 'Hindi mabasa ang istruktura ng dokumento.',
    'The draft and its questions are deleted permanently.' => 'Permanenteng mabubura ang draft at ang mga tanong nito.',
    'The due date has already passed. Choose a new due date so students can hand it in on time.' => 'Lampas na ang takdang araw. Pumili ng bagong takdang araw para maipasa ito ng mga mag-aaral sa tamang oras.',
    'The due date has passed and this assignment does not accept late work.' => 'Lampas na ang takdang araw at hindi tumatanggap ng huling pasa ang gawaing ito.',
    'The due date has passed and this assignment does not accept late work. Talk to your teacher if something got in the way.' => 'Lampas na ang takdang araw at hindi tumatanggap ng huling pasa ang gawaing ito. Kausapin ang iyong guro kung may naging hadlang.',
    'The due date has passed and this quiz no longer accepts attempts.' => 'Lampas na ang takdang araw at hindi na tumatanggap ng pagtatangka ang quiz na ito.',
    'The due date must be after the opening date.' => 'Dapat pagkatapos ng petsa ng pagbubukas ang takdang araw.',
    'The email address is not valid.' => 'Hindi wasto ang email address.',
    'The end date is before the start date.' => 'Mas maaga ang petsa ng pagtatapos kaysa sa petsa ng pagsisimula.',
    'The end date must be on or after the start date.' => 'Dapat kapareho o pagkatapos ng petsa ng pagsisimula ang petsa ng pagtatapos.',
    'The export file has expired and was removed.' => 'Nag-expire na at inalis ang export file.',
    'The file content does not match its extension.' => 'Hindi tugma ang laman ng file sa extension nito.',
    'The file could not be kept on this device. Check the connection and the free space, then try again.' => 'Hindi maitago ang file sa device na ito. Tingnan ang koneksiyon at ang natitirang espasyo, saka subukang muli.',
    'The file could not be removed from this device. Try again.' => 'Hindi maalis ang file sa device na ito. Subukang muli.',
    'The file could not be uploaded. Try again.' => 'Hindi ma-upload ang file. Subukang muli.',
    'The file has a header row but no competencies.' => 'May hanay ng pamagat ang file pero walang kasanayan.',
    'The file has a header row but no people.' => 'May hilera ng header ang file pero walang nakalistang tao.',
    'The file has more than :n rows. Split it into smaller files.' => 'Mahigit :n hilera ang file. Hatiin ito sa mas maliliit na file.',
    'The file is created now and the requester is notified.' => 'Gagawin na ngayon ang file at aabisuhan ang humiling.',
    'The file is empty.' => 'Walang laman ang file.',
    'The file is larger than the :max MB limit.' => 'Lampas ang file sa limitasyong :max MB.',
    'The file is missing from storage. Ask the person who uploaded it to upload it again.' => 'Nawawala ang file sa storage. Hilingin sa nag-upload nito na i-upload itong muli.',
    'The final grade is the average of the period grades. Your school has not switched a transmutation table on.' => 'Ang pangwakas na grado ay ang karaniwan ng mga grado ng bawat panahon. Hindi pa pinagagana ng iyong paaralan ang isang talahanayan ng transmutasyon.',
    'The first row must name the columns. Missing: :cols. Download the template to see the expected layout.' => 'Dapat nakasulat sa unang hilera ang mga pangalan ng column. Kulang: :cols. I-download ang template para makita ang inaasahang ayos.',
    'The grade level is longer than 40 characters' => 'Mas mahaba sa 40 karakter ang baitang',
    'The gradebook fills in as students submit published work and you grade it.' => 'Napupunan ang talaan ng grado habang nagpapasa ang mga mag-aaral ng na-publish na gawain at minamarkahan mo ito.',
    'The highest possible score. Questions or a rubric, if you add them, set this automatically.' => 'Ang pinakamataas na posibleng iskor. Kung magdadagdag ka ng mga tanong o rubric, awtomatiko itong maitatakda.',
    'The initial grade :min appears more than once.' => 'Higit sa isang beses lumalabas ang paunang gradong :min.',
    'The invitation links are no longer available here. Create new links or slips from each person\'s page.' => 'Hindi na makukuha rito ang mga link ng imbitasyon. Gumawa ng bagong link o slip mula sa pahina ng bawat tao.',
    'The key points of one class material, with page references.' => 'Ang mahahalagang punto ng isang materyal ng klase, may kasamang numero ng pahina.',
    'The latest answer recorded from the guardian is no, but the companion is on for this student.' => 'Ang huling sagot na naitala mula sa magulang o guardian ay "hindi", pero naka-on ang companion para sa mag-aaral na ito.',
    'The learning companion' => 'Ang kasama sa pag-aaral',
    'The link works once and expires in :time.' => 'Isang beses lamang gagana ang link at mag-e-expire ito sa loob ng :time.',
    'The link works once and expires in :time. Your current password keeps working until you use it.' => 'Isang beses lamang gagana ang link at mag-e-expire ito sa loob ng :time. Gagana pa rin ang kasalukuyan mong password hanggang gamitin mo ito.',
    'The link you created earlier will stop working.' => 'Titigil sa paggana ang link na ginawa mo kanina.',
    'The lowest row must start at an initial grade of 0, so every grade has a row.' => 'Dapat magsimula sa paunang gradong 0 ang pinakamababang hilera, para may hilera ang bawat grado.',
    'The module is removed; its materials and assignments stay in the class.' => 'Aalisin ang modyul; mananatili sa klase ang mga materyal at gawain nito.',
    'The next time they open B.E.S.T. Learning and Interactive Study System, people will have to read and accept the privacy notice and the rules again.' => 'Sa susunod nilang pagbukas ng B.E.S.T. Learning and Interactive Study System, kailangang basahin at tanggapin muli ng mga tao ang abiso sa privacy at ang mga patakaran.',
    'The oldest arrived :when.' => 'Dumating ang pinakaluma :when.',
    'The page is where they were when they opened "Send feedback". B.E.S.T. Learning and Interactive Study System keeps only its address, never what was on it.' => 'Ang pahina ay kung nasaan sila nang buksan nila ang "Magpadala ng feedback". Ang address lamang nito ang itinatago ng B.E.S.T. Learning and Interactive Study System, hindi kailanman ang laman nito.',
    'The page may have moved, or the address may be mistyped. If you followed a link inside B.E.S.T. Learning and Interactive Study System, the item may have been archived or you may not have access to it.' => 'Maaaring nailipat ang pahina, o mali ang pagkaka-type ng address. Kung sumunod ka sa isang link sa loob ng B.E.S.T. Learning and Interactive Study System, maaaring na-archive ang item o wala kang access dito.',
    'The passages found only partly match the question.' => 'Bahagya lamang tumutugma sa tanong ang mga siping nakita.',
    'The passages that best match your question:' => 'Ang mga siping pinakatugma sa iyong tanong:',
    'The period grade is the initial grade transmuted with your school\'s table.' => 'Ang grado ng panahon ay ang paunang grado na na-transmute gamit ang talahanayan ng iyong paaralan.',
    'The period grade is worked out from this period\'s work only.' => 'Kinukuwenta ang grado ng panahon mula lamang sa mga gawain ng panahong ito.',
    'The practice set could not be prepared. Try again.' => 'Hindi maihanda ang set ng pagsasanay. Subukang muli.',
    'The presentation could not be opened. Save it again and re-upload.' => 'Hindi mabuksan ang presentation. I-save itong muli at i-upload ulit.',
    'The problem is solved or the idea was used.' => 'Nalutas na ang problema o nagamit na ang ideya.',
    'The quarter must be 1 to 4' => 'Dapat 1 hanggang 4 ang markahan',
    'The question has no competency now.' => 'Wala nang kasanayan ang tanong.',
    'The reported answer' => 'Ang ini-report na sagot',
    'The request could not be completed (error :status).' => 'Hindi natapos ang kahilingan (error :status).',
    'The request could not be completed.' => 'Hindi natapos ang kahilingan.',
    'The reset did not finish: :error' => 'Hindi natapos ang pag-reset: :error',
    'The rest of their work is unaffected.' => 'Hindi naaapektuhan ang iba pa niyang gawain.',
    'The rows of the Daily Lesson Log in DepEd Order No. 42, s. 2016, filled from this lesson\'s current draft. Rows B.E.S.T. Learning and Interactive Study System has nothing for are left blank to write in.' => 'Ang mga hanay ng Pang-araw-araw na Tala sa Pagtuturo sa DepEd Order No. 42, s. 2016, pinunan mula sa kasalukuyang draft ng araling ito. Iniiwang blangko ang mga hanay na walang laman mula sa B.E.S.T. Learning and Interactive Study System para masulatan.',
    'The same check runs from a terminal with: php bin/sibol.php check' => 'Mapapatakbo rin ang parehong pagsusuri mula sa terminal gamit ang: php bin/sibol.php check',
    'The same checks run from the command line with: php bin/sibol.php check' => 'Mapapatakbo rin ang parehong mga pagsusuri mula sa command line gamit ang: php bin/sibol.php check',
    'The same code is on line :n' => 'Nasa linya :n din ang parehong code',
    'The same email appears on line :line.' => 'Lumalabas din ang parehong email sa linya :line.',
    'The same username appears on line :line.' => 'Lumalabas din ang parehong username sa linya :line.',
    'The school needs at least one active administrator.' => 'Kailangan ng paaralan ng kahit isang aktibong administrador.',
    'The school starts every student\'s AI off.' => 'Naka-off sa simula ang AI ng bawat mag-aaral sa paaralan.',
    'The school starts every student\'s AI on.' => 'Naka-on sa simula ang AI ng bawat mag-aaral sa paaralan.',
    'The school\'s AI service is not set up correctly right now. Tell your teacher or the school administrator. Everything else in B.E.S.T. Learning and Interactive Study System works as usual.' => 'Hindi tama ang pagkaka-set up ng AI service ng paaralan ngayon. Sabihin sa iyong guro o sa administrador ng paaralan. Gumagana pa rin nang normal ang lahat ng iba pa sa B.E.S.T. Learning and Interactive Study System.',
    'The section has no adviser now.' => 'Wala nang adviser ang seksiyon.',
    'The slip has a one-time code. Hand it to the person yourself.' => 'May isang beses na code ang slip. Ikaw mismo ang mag-abot nito sa tao.',
    'The student can change their answers and submit again. Marks for this attempt are cleared until then.' => 'Maaaring baguhin ng mag-aaral ang kanyang mga sagot at ipasa itong muli. Buburahin ang mga marka ng pagtatangkang ito hanggang doon.',
    'The student can edit and submit again. Any score you entered is cleared.' => 'Maaaring i-edit at ipasang muli ng mag-aaral. Mabubura ang anumang iskor na inilagay mo.',
    'The student must already have a B.E.S.T. Learning and Interactive Study System account at your school.' => 'Dapat ay may B.E.S.T. Learning and Interactive Study System account na ang mag-aaral sa iyong paaralan.',
    'The suggestion could not be prepared. Try again.' => 'Hindi maihanda ang mungkahi. Subukang muli.',
    'The table is empty.' => 'Walang laman ang talahanayan.',
    'The tables could not be created: :error' => 'Hindi magawa ang mga table: :error',
    'The test email could not be sent. Check the MAIL_ settings in .env, then look in storage/logs/sibol.log for the reason.' => 'Hindi maipadala ang pansubok na email. Suriin ang mga setting na MAIL_ sa .env, saka tingnan sa storage/logs/sibol.log ang dahilan.',
    'The two passwords do not match.' => 'Hindi magkatugma ang dalawang password.',
    'The upload did not finish. Try again.' => 'Hindi natapos ang upload. Subukang muli.',
    'The upload is too large' => 'Masyadong malaki ang upload',
    'The username can have 3 to 40 small letters, digits, dots, hyphens or underscores.' => 'Puwedeng may 3 hanggang 40 maliliit na titik, numero, tuldok, gitling o underscore ang username.',
    'The username or password is not correct.' => 'Mali ang username o password.',
    'The weights for :group add up to :sum% with the current categories. Check them below.' => ':sum% ang kabuuan ng mga timbang ng :group sa kasalukuyang mga kategorya. Suriin ang mga ito sa ibaba.',
    'The weights for :group add up to :sum%. They must add up to 100%.' => ':sum% ang kabuuan ng mga timbang ng :group. Dapat itong umabot sa 100%.',
    'The whole conversation is deleted permanently. This cannot be undone.' => 'Permanenteng mabubura ang buong usapan. Hindi na ito maibabalik.',
    'Their own due date' => 'Sariling takdang araw',
    'There are no readable class materials to practise from yet. Choose another class or material, or ask your teacher to share notes.' => 'Wala pang nababasang materyal ng klase na mapagsasanayan. Pumili ng ibang klase o materyal, o hilingin sa iyong guro na magbahagi ng mga tala.',
    'There is no typed response to suggest a grade for. Attached files are not sent to the AI service.' => 'Walang tinipang sagot na mabibigyan ng mungkahing grado. Hindi ipinapadala sa AI service ang mga kalakip na file.',
    'There is nothing to import from this file.' => 'Walang mai-import mula sa file na ito.',
    'There is nothing to regenerate yet.' => 'Wala pang mabubuong muli.',
    'There was nothing graded waiting to be released.' => 'Walang gawaing may grado na naghihintay mailabas.',
    'These materials do not have enough complete sentences to build practice from in demo mode. Try another material.' => 'Walang sapat na buong pangungusap ang mga materyal na ito para makabuo ng pagsasanay sa demo mode. Subukan ang ibang materyal.',
    'They open it, read the privacy notice and set a password.' => 'Bubuksan niya ito, babasahin ang abiso sa privacy at magtatakda ng password.',
    'They see this in their account settings. Required when declining.' => 'Makikita niya ito sa mga setting ng kanyang account. Kailangan kapag tinatanggihan.',
    'Thinking' => 'Nag-iisip',
    'Thinking…' => 'Nag-iisip…',
    'This PDF could not be read. Try saving it again as a PDF, or upload a DOCX instead.' => 'Hindi mabasa ang PDF na ito. Subukang i-save itong muli bilang PDF, o mag-upload na lang ng DOCX.',
    'This PDF is password-protected or encrypted. Save an unprotected copy and upload it again.' => 'May password o naka-encrypt ang PDF na ito. Mag-save ng kopyang walang proteksiyon at i-upload itong muli.',
    'This account has been deactivated. Contact your school administrator if you need access.' => 'Na-deactivate na ang account na ito. Makipag-ugnayan sa administrador ng paaralan kung kailangan mo ng access.',
    'This account no longer exists, so a reply cannot reach anyone.' => 'Wala na ang account na ito, kaya walang maaabot ang tugon.',
    'This account was erased and can no longer be edited.' => 'Binura na ang account na ito at hindi na mae-edit.',
    'This account was erased and cannot be reactivated. Invite the person again with a new account.' => 'Binura na ang account na ito at hindi na maa-activate muli. Imbitahan muli ang tao gamit ang bagong account.',
    'This account was erased on :date after a deletion request. Personal details were removed; the record is kept so past class activity stays consistent.' => 'Binura ang account na ito noong :date matapos ang isang kahilingan sa pagbura. Inalis ang mga personal na detalye; itinatago ang talaan para manatiling magkakatugma ang nakaraang aktibidad sa klase.',
    'This answer and your note will be sent to your school\'s administrators so they can look into it. The rest of the conversation is not sent.' => 'Ipapadala ang sagot na ito at ang iyong tala sa mga administrador ng iyong paaralan para masuri nila. Hindi ipapadala ang iba pang bahagi ng usapan.',
    'This assignment cannot be changed now.' => 'Hindi na mababago ang gawaing ito ngayon.',
    'This assignment is closed, so it no longer accepts work.' => 'Sarado na ang gawaing ito, kaya hindi na ito tumatanggap ng pasa.',
    'This assignment is closed.' => 'Sarado na ang gawaing ito.',
    'This attempt has already been submitted.' => 'Naipasa na ang pagtatangkang ito.',
    'This attempt is no longer open.' => 'Hindi na bukas ang pagtatangkang ito.',
    'This class is archived.' => 'Naka-archive ang klaseng ito.',
    'This conversation is archived. Restore it to continue.' => 'Naka-archive ang usapang ito. Ibalik ito para magpatuloy.',
    'This conversation is not linked to a class, so there is no teacher to share with.' => 'Hindi nakakabit sa isang klase ang usapang ito, kaya walang gurong mapagbabahagian.',
    'This conversation is private to you and is deleted after :days days.' => 'Pribado sa iyo ang usapang ito at buburahin pagkalipas ng :days araw.',
    'This conversation is private to you.' => 'Pribado sa iyo ang usapang ito.',
    'This copy shows the correct answers. Keep it away from students; only teachers of this class can open it.' => 'Ipinapakita ng kopyang ito ang mga tamang sagot. Ilayo ito sa mga mag-aaral; mga guro lamang ng klaseng ito ang makapagbubukas nito.',
    'This database already has a school. Use “Reset demo data” to start again.' => 'May paaralan na ang database na ito. Gamitin ang “I-reset ang demo data” para magsimulang muli.',
    'This deletes every record in the :name database and loads the demo school again.' => 'Buburahin nito ang bawat talaan sa database na :name at ilo-load muli ang demo na paaralan.',
    'This draft was written with AI from your materials. Check facts, examples and reading level, and adapt it to your class before publishing.' => 'Isinulat ang draft na ito gamit ang AI mula sa iyong mga materyal. Suriin ang mga impormasyon, halimbawa at antas ng pagbasa, at iangkop ito sa iyong klase bago i-publish.',
    'This email belongs to an account outside your school.' => 'Ang email na ito ay sa isang account na nasa labas ng iyong paaralan.',
    'This export is not available. Exports can be downloaded for 14 days; ask for a new one if it has expired.' => 'Hindi magagamit ang export na ito. Mada-download ang mga export sa loob ng 14 na araw; humingi ng bago kung nag-expire na ito.',
    'This file type cannot be read for the companion yet. It can still be downloaded by students.' => 'Hindi pa mababasa para sa companion ang ganitong uri ng file. Mada-download pa rin ito ng mga mag-aaral.',
    'This file type is available to download but cannot be read by the companion.' => 'Mada-download ang ganitong uri ng file pero hindi ito mababasa ng companion.',
    'This file type is not supported. Use :types.' => 'Hindi suportado ang uri ng file na ito. Gamitin ang :types.',
    'This form expired' => 'Nag-expire ang form na ito',
    'This form expired before it was sent. Reload the page and try again.' => 'Nag-expire ang form bago ito naipadala. I-reload ang pahina at subukang muli.',
    'This invitation link is no longer valid' => 'Hindi na wasto ang link ng imbitasyong ito',
    'This is the current period' => 'Ito ang kasalukuyang panahong akademiko',
    'This is the only active administrator, so it cannot be deactivated.' => 'Ito lamang ang aktibong administrador, kaya hindi ito maaaring i-deactivate.',
    'This is what students see. Answer keys and explanations stay hidden until your release setting allows them. Nothing you do here is saved.' => 'Ito ang nakikita ng mga mag-aaral. Mananatiling nakatago ang susi sa pagwawasto at mga paliwanag hanggang payagan ng iyong setting sa paglalabas. Walang nase-save sa anumang gagawin mo rito.',
    'This month' => 'Ngayong buwan',
    'This month, as a list' => 'Ngayong buwan, bilang listahan',
    'This notice describes how this installation of B.E.S.T. Learning and Interactive Study System actually works. The school must review it with its data protection officer and legal adviser before using B.E.S.T. Learning and Interactive Study System with real student information; technical safeguards alone do not make a school compliant.' => 'Inilalarawan ng abisong ito kung paano talaga gumagana ang installation na ito ng B.E.S.T. Learning and Interactive Study System. Dapat itong suriin ng paaralan kasama ang data protection officer at legal adviser nito bago gamitin ang B.E.S.T. Learning and Interactive Study System sa tunay na impormasyon ng mga mag-aaral; hindi sapat ang mga teknikal na proteksiyon lamang para masabing sumusunod sa batas ang isang paaralan.',
    'This page appears only in local mode and only on this computer. It prepares the MySQL database and can load a fictional demo school.' => 'Lumalabas lamang ang pahinang ito sa local mode at sa computer na ito lamang. Inihahanda nito ang MySQL database at maaari itong mag-load ng kathang-isip na demo na paaralan.',
    'This page could not be found' => 'Hindi mahanap ang pahinang ito',
    'This password link is no longer valid' => 'Hindi na wasto ang link na ito para sa password',
    'This permanently removes their personal data and cannot be undone.' => 'Permanente nitong aalisin ang kanyang personal na datos at hindi na ito maibabalik.',
    'This practice set and its results will be removed.' => 'Aalisin ang set ng pagsasanay na ito at ang mga resulta nito.',
    'This preview has expired or was already imported. Upload the file again.' => 'Nag-expire na ang preview na ito o na-import na. I-upload muli ang file.',
    'This question will be removed.' => 'Aalisin ang tanong na ito.',
    'This quiz has no published questions yet.' => 'Wala pang na-publish na tanong ang quiz na ito.',
    'This quiz is closed.' => 'Sarado na ang quiz na ito.',
    'This replaces your current categories, subject groups, transmutation table and descriptors.' => 'Papalitan nito ang iyong kasalukuyang mga kategorya, pangkat ng asignatura, talahanayan ng transmutasyon at mga deskriptor.',
    'This request is about your own account, so another administrator must handle it.' => 'Tungkol sa sarili mong account ang kahilingang ito, kaya ibang administrador ang dapat humawak nito.',
    'This school year already has grading periods, or is too short to split.' => 'May mga panahon ng pagmamarka na ang taong panuruang ito, o masyado itong maikli para hatiin.',
    'This school year so far' => 'Ang taong panuruang ito sa ngayon',
    'This section is too long (12,000 characters at most).' => 'Masyadong mahaba ang bahaging ito (hanggang 12,000 character lamang).',
    'This test email from B.E.S.T. Learning and Interactive Study System at :school arrived, so email is set up correctly.' => 'Dumating ang pansubok na email na ito mula sa B.E.S.T. Learning and Interactive Study System sa :school, kaya tama ang pagkaka-set up ng email.',
    'This username belongs to an account outside your school.' => 'Pag-aari ng account sa labas ng iyong paaralan ang username na ito.',
    'This week' => 'Ngayong linggo',
    'This work has no grading category, so its scores are left out of every grade in the gradebook.' => 'Walang kategorya ng pagmamarka ang gawaing ito, kaya hindi isinasama ang mga iskor nito sa anumang grado sa talaan ng grado.',
    'This work has not been submitted yet.' => 'Hindi pa naipapasa ang gawaing ito.',
    'This work opens :date.' => 'Magbubukas ang gawaing ito sa :date.',
    'Those sessions are already on your calendar or are in the past.' => 'Nasa kalendaryo mo na ang mga sesyong iyon o lumipas na ang mga ito.',
    'Those slips are no longer shown here. Codes on slips you already printed keep working until they are used or expire; print new ones if you need them.' => 'Hindi na ipinapakita rito ang mga slip na iyon. Gagana pa rin ang mga code sa mga slip na na-print mo na hanggang magamit o mag-expire ang mga ito; mag-print ng bago kung kailangan.',
    'Tick that you have checked every line against the official order before switching the table on.' => 'Lagyan ng tsek na nasuri mo ang bawat linya laban sa opisyal na kautusan bago paganahin ang talahanayan.',
    'Tick the cards you knew, then save.' => 'Lagyan ng tsek ang mga card na alam mo, saka i-save.',
    'Tick this to agree to the rules for using B.E.S.T. Learning and Interactive Study System.' => 'Lagyan ito ng tsek para sumang-ayon sa mga patakaran sa paggamit ng B.E.S.T. Learning and Interactive Study System.',
    'Tick this to confirm you have read the privacy notice.' => 'Lagyan ito ng tsek para kumpirmahing nabasa mo ang abiso sa privacy.',
    'Time is up. Reconnect to finish: the quiz will be submitted with the answers that reached the server in time.' => 'Ubos na ang oras. Kumonekta muli para matapos: ipapasa ang quiz kasama ang mga sagot na umabot sa server sa tamang oras.',
    'Time left' => 'Natitirang oras',
    'Time limit' => 'Takdang oras',
    'Time limit (minutes)' => 'Takdang oras (minuto)',
    'Time range' => 'Saklaw ng panahon',
    'Time was up, so your saved answers were submitted.' => 'Naubos na ang oras, kaya naipasa ang mga na-save mong sagot.',
    'Time-based, 6 digits' => 'Batay sa oras, 6 na numero',
    'Timezone' => 'Timezone',
    'Title' => 'Pamagat',
    'Title, topic or description' => 'Pamagat, paksa o paglalarawan',
    'To' => 'Hanggang',
    'To ask for a copy of your data, a correction, or deletion, open Account and choose a privacy request. The school reviews each request; some school records may have to be kept by law or policy, and you will be told if so.' => 'Para humingi ng kopya ng iyong datos, pagtatama, o pagbura, buksan ang Account at pumili ng kahilingan sa privacy. Sinusuri ng paaralan ang bawat kahilingan; maaaring kailangang itago ang ilang talaan ng paaralan ayon sa batas o patakaran, at sasabihan ka kung ganoon.',
    'To do' => 'Gagawin',
    'To grade' => 'Mamarkahan',
    'To join a class, open Classes and enter the code your teacher gives you.' => 'Para sumali sa klase, buksan ang Mga klase at ilagay ang code na ibinigay ng iyong guro.',
    'To review' => 'Susuriin',
    'Today' => 'Ngayong araw',
    'Today\'s reviews are done' => 'Tapos na ang pagbabalik-aral ngayong araw',
    'Tokens' => 'Mga token',
    'Too many attempts' => 'Masyadong maraming pagtatangka',
    'Too many codes that did not match. Wait 15 minutes, then sign in again.' => 'Masyadong maraming code na hindi tugma. Maghintay ng 15 minuto, saka mag-sign in muli.',
    'Too many sign-in attempts. Wait 15 minutes, then try again.' => 'Masyadong maraming pagtatangkang mag-sign in. Maghintay ng 15 minuto, saka subukang muli.',
    'Too many tries. Wait 10 minutes, then check the code with your teacher.' => 'Masyadong maraming pagsubok. Maghintay ng 10 minuto, saka itanong ang code sa iyong guro.',
    'Too many tries. Wait 15 minutes, then try again.' => 'Masyadong maraming pagsubok. Maghintay ng 15 minuto, saka subukang muli.',
    'Topic' => 'Paksa',
    'Topics appear once students have answered automatically marked questions that have a topic set.' => 'Lalabas ang mga paksa kapag nasagot na ng mga mag-aaral ang mga tanong na awtomatikong minamarkahan at may nakatakdang paksa.',
    'Topics that may need reteaching' => 'Mga paksang maaaring kailangang ituro muli',
    'Topics, by share of correct answers' => 'Mga paksa, ayon sa bahagdan ng tamang sagot',
    'Total' => 'Kabuuan',
    'Total points' => 'Kabuuang puntos',
    'Total:' => 'Kabuuan:',
    'Totals by subject across all classes. Groups smaller than :n are hidden so individual students cannot be identified.' => 'Kabuuan bawat asignatura sa lahat ng klase. Nakatago ang mga grupong mas maliit sa :n para hindi makilala ang indibidwal na mag-aaral.',
    'Transmutation' => 'Transmutasyon',
    'Transmutation table' => 'Talahanayan ng transmutasyon',
    'Treated as :name (:username), who already has an account with this name. To add a different person with the same name, give them a username in the file.' => 'Itinuring na si :name (:username), na may account na sa pangalang ito. Para magdagdag ng ibang tao na kapareho ang pangalan, bigyan siya ng username sa file.',
    'Tried to send a test email' => 'Sinubukang magpadala ng pansubok na email',
    'True' => 'Tama',
    'True or false' => 'Tama o mali',
    'Try a shorter word, a class name, or the title of a material.' => 'Subukan ang mas maikling salita, pangalan ng klase, o pamagat ng materyal.',
    'Try a wider date range or another type.' => 'Subukan ang mas malawak na saklaw ng petsa o ibang uri.',
    'Try again' => 'Subukang muli',
    'Try again in a moment.' => 'Subukang muli mamaya.',
    'Try different key words, or ask your teacher.' => 'Subukan ang ibang mga susing salita, o magtanong sa iyong guro.',
    'Try this: cover the list, then write the main idea of each part from memory.' => 'Subukan ito: takpan ang listahan, saka isulat mula sa alaala ang pangunahing ideya ng bawat bahagi.',
    'Turn off code' => 'I-off ang code',
    'Turn on two-step sign-in' => 'I-on ang dalawang-hakbang na pag-sign in',
    'Turned off' => 'Naka-off',
    'Turned off a class code' => 'Nag-off ng class code',
    'Turned off two-step sign-in' => 'Ini-off ang dalawang-hakbang na pag-sign in',
    'Turned on two-step sign-in' => 'Ini-on ang dalawang-hakbang na pag-sign in',
    'Turning this off hides the companion and AI drafting for everyone. Everything else keeps working.' => 'Kapag in-off ito, maitatago ang companion at ang pagbuo ng draft gamit ang AI para sa lahat. Patuloy na gagana ang lahat ng iba pa.',
    'Turns off animations, in addition to your device setting.' => 'Ino-off ang mga animation, bukod pa sa setting ng iyong device.',
    'Two minutes left. Your answers are saved as you go.' => 'Dalawang minuto na lang. Nase-save ang iyong mga sagot habang sumasagot ka.',
    'Two-step sign-in' => 'Dalawang-hakbang na pag-sign in',
    'Two-step sign-in is not ready on this server yet. A school administrator needs to set APP_KEY (see README).' => 'Hindi pa handa sa server na ito ang dalawang-hakbang na pag-sign in. Kailangang itakda ng administrador ng paaralan ang APP_KEY (tingnan ang README).',
    'Two-step sign-in is off for :name. Their password alone signs them in until they set it up again.' => 'Naka-off na ang dalawang-hakbang na pag-sign in ni :name. Password lang ang kailangan niya para makapag-sign in hanggang i-set up niya ito muli.',
    'Two-step sign-in is off. Your password alone signs you in.' => 'Naka-off na ang dalawang-hakbang na pag-sign in. Password mo lang ang kailangan para makapag-sign in.',
    'Two-step sign-in is on.' => 'Naka-on na ang dalawang-hakbang na pag-sign in.',
    'Two-step sign-in was switched off for your account' => 'Ini-off ang dalawang-hakbang na pag-sign in ng iyong account',
    'Type' => 'Uri',
    'Type a question first.' => 'Mag-type muna ng tanong.',
    'Type at least two characters.' => 'Mag-type ng hindi bababa sa dalawang character.',
    'Type each student\'s score. Leave it empty until you have marked their paper. Students see scores only after you release them.' => 'I-type ang iskor ng bawat mag-aaral. Iwanang blangko hangga\'t hindi mo pa namamarkahan ang kanyang papel. Makikita lamang ng mga mag-aaral ang mga iskor pagkatapos mong ilabas ang mga ito.',
    'Type in the table before switching it on.' => 'I-type muna ang talahanayan bago ito paganahin.',
    'Type of practice' => 'Uri ng pagsasanay',
    'Type of request' => 'Uri ng kahilingan',
    'Type or choose a code from your school\'s list. Leave it empty for none.' => 'I-type o pumili ng code mula sa listahan ng iyong paaralan. Iwanang blangko kung wala.',
    'Type the 12 letters and numbers from your slip, for example ABCD-EFGH-JKMN.' => 'I-type ang 12 titik at numero mula sa iyong slip, halimbawa ABCD-EFGH-JKMN.',
    'Type the new password again' => 'I-type muli ang bagong password',
    'Type the password again' => 'I-type muli ang password',
    'Type the person\'s full name exactly as shown to confirm.' => 'I-type ang buong pangalan ng tao nang eksakto gaya ng nakikita para kumpirmahin.',
    'Type “:name” to confirm' => 'I-type ang “:name” para kumpirmahin',
    'Type: :type' => 'Uri: :type',
    'Typed a sign-in code that did not match' => 'Nag-type ng code sa pag-sign in na hindi tugma',
    'Typed response' => 'Tinipang sagot',
    'USD, estimate' => 'USD, tantiya',
    'Unchanged' => 'Walang binago',
    'Under the Data Privacy Act of 2012 (Republic Act No. 10173) you have the right to be informed, to access your information, to object, to have incorrect information corrected, to ask for erasure or blocking, to receive a copy of your data, and to complain to the National Privacy Commission.' => 'Sa ilalim ng Data Privacy Act of 2012 (Republic Act No. 10173), may karapatan kang malaman, ma-access ang iyong impormasyon, tumutol, ipaitama ang maling impormasyon, humiling na burahin o harangin ito, makatanggap ng kopya ng iyong datos, at magreklamo sa National Privacy Commission.',
    'Undo' => 'Bawiin',
    'Unknown' => 'Hindi alam',
    'Unknown action.' => 'Hindi kilalang aksiyon.',
    'Unknown user' => 'Hindi kilalang user',
    'Unpublish' => 'Bawiin ang pag-publish',
    'Unpublish?' => 'Bawiin ang pag-publish?',
    'Unpublished a lesson' => 'Binawi ang pag-publish ng aralin',
    'Unpublished a material' => 'Binawi ang pag-publish ng materyal',
    'Unpublished changes' => 'Mga pagbabagong hindi pa na-publish',
    'Unpublished. Students can no longer see this lesson.' => 'Binawi ang pag-publish. Hindi na makikita ng mga mag-aaral ang araling ito.',
    'Unread' => 'Hindi pa nababasa',
    'Unread:' => 'Hindi pa nababasa:',
    'Unreleased grades are visible only to you.' => 'Ikaw lamang ang nakakakita ng mga gradong hindi pa inilalabas.',
    'Unsafe or inappropriate' => 'Hindi ligtas o hindi angkop',
    'Unused, expires :date' => 'Hindi pa nagagamit, mag-e-expire sa :date',
    'Up to 1,000 rows and 2 MB. Save from Excel or Google Sheets as “CSV UTF-8”.' => 'Hanggang 1,000 hilera at 2 MB. I-save mula sa Excel o Google Sheets bilang “CSV UTF-8”.',
    'Up to 3,000 rows and 2 MB. Save from Excel or Google Sheets as “CSV UTF-8”.' => 'Hanggang 3,000 hanay at 2 MB. I-save mula sa Excel o Google Sheets bilang “CSV UTF-8”.',
    'Upcoming' => 'Paparating',
    'Update status' => 'I-update ang katayuan',
    'Updated' => 'Na-update',
    'Updated a material' => 'Nag-update ng materyal',
    'Updated a privacy request' => 'Nag-update ng kahilingan sa privacy',
    'Updated a subject' => 'Nag-update ng asignatura',
    'Updated account details' => 'Nag-update ng mga detalye ng account',
    'Updated an academic period' => 'Nag-update ng panahong akademiko',
    'Updated class details' => 'Nag-update ng mga detalye ng klase',
    'Updates about your classes and work will appear here.' => 'Lalabas dito ang mga update tungkol sa iyong mga klase at gawain.',
    'Upload' => 'I-upload',
    'Upload a CSV file. You will see every row and any problems before anyone is added.' => 'Mag-upload ng CSV file. Makikita mo ang bawat hilera at anumang problema bago may maidagdag na tao.',
    'Upload a PDF, Word, PowerPoint or text file, or add a link. Files are read so the companion can quote them with page references.' => 'Mag-upload ng PDF, Word, PowerPoint o text file, o magdagdag ng link. Binabasa ang mga file para masipi ito ng companion nang may numero ng pahina.',
    'Upload a different file' => 'Mag-upload ng ibang file',
    'Upload a logo' => 'Mag-upload ng logo',
    'Upload a new version' => 'Mag-upload ng bagong bersiyon',
    'Upload logo' => 'I-upload ang logo',
    'Upload material' => 'Mag-upload ng materyal',
    'Upload materials to a class, then publish them. Only published, released materials are visible to students and to the companion.' => 'Mag-upload ng mga materyal sa isang klase, saka i-publish ang mga ito. Ang mga na-publish at nailabas na materyal lamang ang nakikita ng mga mag-aaral at ng companion.',
    'Upload photo' => 'Mag-upload ng larawan',
    'Upload version' => 'I-upload ang bersiyon',
    'Uploaded' => 'Na-upload',
    'Uploaded a new version of a material' => 'Nag-upload ng bagong bersiyon ng materyal',
    'Uploaded. B.E.S.T. Learning and Interactive Study System is reading the file so the companion can use it.' => 'Na-upload. Binabasa ng B.E.S.T. Learning and Interactive Study System ang file para magamit ito ng companion.',
    'Uploading…' => 'Ina-upload…',
    'Usage details' => 'Mga detalye ng paggamit',
    'Use 200 characters or fewer.' => 'Gumamit ng hindi hihigit sa 200 character.',
    'Use 3 to 40 small letters, digits, dots, hyphens or underscores, starting and ending with a letter or digit.' => 'Gumamit ng 3 hanggang 40 maliliit na titik, numero, tuldok, gitling o underscore, na nagsisimula at nagtatapos sa titik o numero.',
    'Use 30 grade levels or fewer.' => 'Gumamit ng hindi hihigit sa 30 baitang.',
    'Use a sign-in slip' => 'Gumamit ng slip sa pag-sign in',
    'Use at least 10 characters.' => 'Gumamit ng hindi bababa sa 10 character.',
    'Use by' => 'Gamitin hanggang',
    'Use my class notes' => 'Gamitin ang mga tala ng aking klase',
    'Use real school records only with your school\'s permission.' => 'Gumamit lamang ng tunay na rekord ng paaralan nang may pahintulot ng iyong paaralan.',
    'Use real student information only as your school\'s data protection officer allows.' => 'Gumamit lamang ng tunay na impormasyon ng mag-aaral ayon sa pinapayagan ng data protection officer ng iyong paaralan.',
    'Use the rubric below.' => 'Gamitin ang rubric sa ibaba.',
    'Use the school\'s timezone (:tz)' => 'Gamitin ang timezone ng paaralan (:tz)',
    'Use the username on your sign-in slip. Teachers can also use their email address.' => 'Gamitin ang username sa iyong slip sa pag-sign in. Maaari ring gamitin ng mga guro ang kanilang email address.',
    'Use them to decide what to revisit, not to label students.' => 'Gamitin ang mga ito sa pagpapasya kung ano ang babalikan, hindi sa pagtatatak sa mga mag-aaral.',
    'Use this after your school changes how it uses B.E.S.T. Learning and Interactive Study System, for example a new privacy contact or a decision by your data protection officer. Everyone the policy names reads and accepts the notice and the rules again before they continue.' => 'Gamitin ito kapag binago ng iyong paaralan kung paano nito ginagamit ang B.E.S.T. Learning and Interactive Study System, halimbawa may bagong contact sa privacy o may pasya ang inyong data protection officer. Babasahin at tatanggaping muli ng lahat ng saklaw ng patakaran ang abiso at ang mga patakaran bago sila magpatuloy.',
    'Use this mode' => 'Gamitin ang mode na ito',
    'Use this table for grading period grades' => 'Gamitin ang talahanayang ito para sa mga grado ng panahon ng pagmamarka',
    'Use your school Google account (:domains).' => 'Gamitin ang Google account ng iyong paaralan (:domains).',
    'Used :count time' => 'Nagamit nang :count beses',
    'Used :count times' => 'Nagamit nang :count beses',
    'Used by existing assignments' => 'Ginagamit ng mga kasalukuyang gawain',
    'Used for search and filters.' => 'Ginagamit sa paghahanap at pagsasala.',
    'Used in insights to show which topics need reteaching.' => 'Ginagamit sa insights para ipakita kung aling mga paksa ang kailangang ituro muli.',
    'Used on' => 'Ginamit sa',
    'Used to sign in. Changing it takes effect at their next sign-in.' => 'Ginagamit sa pag-sign in. Magkakabisa ang pagbabago sa susunod nilang pag-sign in.',
    'Used to sign in. Leave empty and B.E.S.T. Learning and Interactive Study System makes one from the name, such as juan.delacruz.' => 'Ginagamit sa pag-sign in. Iwanang blangko at gagawa ang B.E.S.T. Learning and Interactive Study System mula sa pangalan, gaya ng juan.delacruz.',
    'Used to suggest students when adding members.' => 'Ginagamit para magmungkahi ng mga mag-aaral kapag nagdaragdag ng mga miyembro.',
    'Username' => 'Username',
    'Username made from the name' => 'Username na gagawin mula sa pangalan',
    'Username or email' => 'Username o email',
    'Using B.E.S.T. Learning and Interactive Study System honestly and safely, and what the AI companion will and will not do for you.' => 'Tapat at ligtas na paggamit ng B.E.S.T. Learning and Interactive Study System, at kung ano ang gagawin at hindi gagawin ng AI companion para sa iyo.',
    'V. Remarks' => 'V. Mga tala',
    'VI. Reflection' => 'VI. Pagninilay',
    'Variations of an activity for different readiness levels.' => 'Mga bersiyon ng gawain para sa iba\'t ibang antas ng kahandaan.',
    'Version :n' => 'Bersiyon :n',
    'Versions' => 'Mga bersiyon',
    'View' => 'Tingnan',
    'Visibility' => 'Sino ang makakakita',
    'Visible to you because you teach this class. Use it to follow up, not to rank students.' => 'Nakikita mo ito dahil ikaw ang nagtuturo sa klaseng ito. Gamitin ito sa pagsubaybay, hindi sa pagraranggo ng mga mag-aaral.',
    'Vocabulary and translation' => 'Bokabularyo at salin',
    'Waiting for the latest extension: :date' => 'Hinihintay ang pinakahuling palugit: :date',
    'Waiting for your score' => 'Hinihintay ang iyong iskor',
    'Waiting for your teacher' => 'Naghihintay sa iyong guro',
    'Waiting to be read' => 'Naghihintay mabasa',
    'Was due today at :time' => 'Ang takdang oras ay kanina, :time',
    'Was refused access to a page' => 'Hindi pinayagang ma-access ang isang pahina',
    'Ways to explain a concept at your students\' level.' => 'Mga paraan ng pagpapaliwanag ng konsepto sa antas ng iyong mga mag-aaral.',
    'Web address' => 'Web address',
    'Week ending' => 'Katapusan ng linggo',
    'Week starting' => 'Simula ng linggo',
    'Weekly pilot report' => 'Lingguhang ulat ng pilot',
    'Weeks' => 'Mga linggo',
    'Weight %' => 'Timbang %',
    'Weighted categories' => 'Mga kategoryang may timbang',
    'Weighted grading needs at least one category.' => 'Kailangan ng kahit isang kategorya sa pagmamarkang may timbang.',
    'Weights by subject group' => 'Timbang ayon sa pangkat ng asignatura',
    'Weights must add up to 100. Subjects in a group below use the group\'s weights instead. Leave a row empty to remove it.' => 'Dapat umabot sa 100 ang kabuuan ng mga timbang. Ang mga asignaturang nasa isang pangkat sa ibaba ay gumagamit ng timbang ng pangkat. Iwanang blangko ang isang hilera para alisin ito.',
    'Welcome to B.E.S.T. Learning and Interactive Study System. Your account is ready.' => 'Maligayang pagdating sa B.E.S.T. Learning and Interactive Study System. Handa na ang iyong account.',
    'What B.E.S.T. Learning and Interactive Study System keeps' => 'Ano ang itinatago ng B.E.S.T. Learning and Interactive Study System',
    'What administrators can see' => 'Ano ang nakikita ng mga administrador',
    'What are you adding?' => 'Ano ang idinadagdag mo?',
    'What are you preparing?' => 'Ano ang inihahanda mo?',
    'What are you preparing? Name a topic, a lesson or practice items, and I will start from your class materials.' => 'Ano ang inihahanda mo? Magbigay ng paksa, aralin o mga pagsasanay, at magsisimula ako sa mga materyal ng iyong klase.',
    'What difficulties did I encounter which my principal or supervisor can help me solve?' => 'Anong suliranin ang aking naranasan na maaaring malutas sa tulong ng aking punong-guro at superbisor?',
    'What feedback have you decided to give?' => 'Anong feedback ang napagpasyahan mong ibigay?',
    'What happened, or what would help? A sentence or two is enough.' => 'Ano ang nangyari, o ano ang makatutulong? Sapat na ang isa o dalawang pangungusap.',
    'What happens next' => 'Ano ang susunod na mangyayari',
    'What innovation or localized materials did I use or discover which I wish to share with other teachers?' => 'Anong inobasyon o lokal na kagamitang panturo ang aking ginamit o natuklasan na nais kong ibahagi sa mga kapwa ko guro?',
    'What is :term?' => 'Ano ang :term?',
    'What is wrong?' => 'Ano ang mali?',
    'What it is about' => 'Tungkol saan ito',
    'What it looks like' => 'Paglalarawan',
    'What lesson are you planning, and for how long?' => 'Anong aralin ang pinaplano mo, at gaano katagal?',
    'What problem are you working on?' => 'Anong problema ang ginagawa mo?',
    'What should it explain?' => 'Ano ang ipapaliwanag nito?',
    'What should students be able to do by the end? One per line works well.' => 'Ano ang dapat kayang gawin ng mga mag-aaral sa pagtatapos? Mainam ang isa bawat linya.',
    'What should the student change?' => 'Ano ang dapat baguhin ng mag-aaral?',
    'What students and teachers tell the school about B.E.S.T. Learning and Interactive Study System: problems, confusing parts and ideas. Give each a status; a short reply reaches the sender as a notification.' => 'Ang sinasabi ng mga mag-aaral at guro sa paaralan tungkol sa B.E.S.T. Learning and Interactive Study System: mga problema, nakalilitong bahagi at ideya. Bigyan ng katayuan ang bawat isa; ang maikling tugon ay umaabot sa nagpadala bilang notification.',
    'What students should already know.' => 'Ang dapat alam na ng mga mag-aaral.',
    'What students will be able to do.' => 'Ang magagawa ng mga mag-aaral.',
    'What teachers and students will see.' => 'Ang makikita ng mga guro at mag-aaral.',
    'What test or deadline is coming, and when are you free?' => 'Anong test o deadline ang paparating, at kailan ka libre?',
    'What the companion will and will not do' => 'Ang gagawin at hindi gagawin ng companion',
    'What they asked' => 'Ano ang hiniling niya',
    'What they wrote' => 'Ang isinulat nila',
    'What this lesson teaches. Saved with the draft; students do not see it. The Daily Lesson Log lists them with their codes.' => 'Ang itinuturo ng araling ito. Nase-save kasama ng draft; hindi ito nakikita ng mga mag-aaral. Inililista ang mga ito ng Daily Lesson Log kasama ang kanilang mga code.',
    'What this means' => 'Ano ang ibig sabihin nito',
    'What topic should it quiz you on?' => 'Sa anong paksa ka nito bibigyan ng quiz?',
    'What would you like to work on?' => 'Ano ang gusto mong pag-aralan?',
    'What you already know' => 'Ang alam mo na',
    'What you want to do' => 'Ang gusto mong gawin',
    'What you will learn' => 'Ang matututuhan mo',
    'What you will study' => 'Ang pag-aaralan mo',
    'When I release them' => 'Kapag inilabas ko',
    'When an answer uses your class materials, numbered sources appear beside it. Select a number to see the exact passage and page.' => 'Kapag gumagamit ang isang sagot ng mga materyal ng iyong klase, lalabas sa tabi nito ang mga sangguniang may numero. Pumili ng numero para makita ang eksaktong sipi at pahina.',
    'When off, the companion only answers from released class materials and says so when they do not cover a question.' => 'Kapag naka-off, sumasagot lamang ang companion mula sa mga inilabas na materyal ng klase at sinasabi nito kapag hindi saklaw ng mga ito ang isang tanong.',
    'When should students see it?' => 'Kailan ito dapat makita ng mga mag-aaral?',
    'When students do it in class or hand in the paper. It never shows as missing; you enter scores afterwards.' => 'Kung kailan ito ginagawa ng mga mag-aaral sa klase o ipinapasa ang papel. Hindi ito kailanman lumalabas na kulang; ilalagay mo ang mga iskor pagkatapos.',
    'When students see correct answers' => 'Kailan makikita ng mga mag-aaral ang tamang sagot',
    'When students see grades' => 'Kailan makikita ng mga mag-aaral ang grado',
    'When the companion uses class materials, it shows exactly where each point came from.' => 'Kapag gumagamit ng materyal ng klase ang companion, ipinapakita nito kung saan eksaktong nagmula ang bawat punto.',
    'When you ask the companion something, B.E.S.T. Learning and Interactive Study System sends your question, recent messages in that conversation, and the relevant passages from your released class materials to the AI service the school has configured. Your name and email are not included.' => 'Kapag nagtanong ka sa companion, ipinapadala ng B.E.S.T. Learning and Interactive Study System ang iyong tanong, ang mga kamakailang mensahe sa usapang iyon, at ang mga kaugnay na sipi mula sa mga inilabas na materyal ng iyong klase sa AI service na itinakda ng paaralan. Hindi kasama ang iyong pangalan at email.',
    'When you read and accepted this notice and the rules for using B.E.S.T. Learning and Interactive Study System; whether the AI companion is switched on for you; and, if your school recorded one, your parent\'s or guardian\'s yes or no about the AI companion with its date. No signed forms are stored in B.E.S.T. Learning and Interactive Study System.' => 'Kailan mo binasa at tinanggap ang abisong ito at ang mga patakaran sa paggamit ng B.E.S.T. Learning and Interactive Study System; kung naka-on ang AI companion para sa iyo; at, kung may itinala ang iyong paaralan, ang oo o hindi ng iyong magulang o guardian tungkol sa AI companion kasama ang petsa nito. Walang pinirmahang form na iniimbak sa B.E.S.T. Learning and Interactive Study System.',
    'When you release them' => 'Kapag inilabas mo',
    'When your teacher shares notes, files or links, they will appear here, organised by module.' => 'Kapag nagbahagi ang iyong guro ng mga tala, file o link, lalabas ang mga ito rito, nakaayos ayon sa modyul.',
    'When your teachers release grades and comments, you will find them here.' => 'Kapag inilabas ng iyong mga guro ang mga grado at komento, makikita mo ang mga ito rito.',
    'Which activity do you want to adapt?' => 'Aling gawain ang gusto mong iangkop?',
    'Which concept do your students find hard?' => 'Aling konsepto ang nahihirapan ang iyong mga mag-aaral?',
    'Which copy' => 'Aling kopya',
    'Which of my teaching strategies worked well? Why did these work?' => 'Alin sa mga istratehiya ko sa pagtuturo ang nakatulong nang lubos? Bakit ito nakatulong?',
    'Which words or terms?' => 'Aling mga salita o termino?',
    'While you take a quiz, answers that have not reached B.E.S.T. Learning and Interactive Study System yet are kept in that browser tab only, and removed once they arrive, when you submit, or when you sign out.' => 'Habang sumasagot ka sa quiz, ang mga sagot na hindi pa umaabot sa B.E.S.T. Learning and Interactive Study System ay nakatago lamang sa tab na iyon ng browser, at binubura kapag dumating na ang mga ito, kapag nagpasa ka, o kapag nag-sign out ka.',
    'Who can see it' => 'Sino ang makakakita nito',
    'Who is responsible' => 'Sino ang may pananagutan',
    'Who may need a nudge' => 'Sino ang maaaring kailangang paalalahanan',
    'Will be added' => 'Idaragdag',
    'Will be added to class' => 'Idaragdag sa klase',
    'Will be invited' => 'Iimbitahan',
    'Will be updated' => 'Ia-update',
    'With an AI provider connected, B.E.S.T. Learning and Interactive Study System would draft from these passages for you to review.' => 'Kapag may nakakonektang AI provider, bubuo ang B.E.S.T. Learning and Interactive Study System ng draft mula sa mga siping ito para suriin mo.',
    'With answer key' => 'May susi sa pagwawasto',
    'With so few results this can change a lot.' => 'Dahil kaunti pa lamang ang resulta, maaari pa itong magbago nang malaki.',
    'Withdrawn :date' => 'Inalis noong :date',
    'Withdrew a student from a class' => 'Inalis ang isang mag-aaral sa klase',
    'Won\'t fix' => 'Hindi aayusin',
    'Work' => 'Gawain',
    'Work a teacher placed in :name by hand will count by its due date instead.' => 'Ang mga gawaing inilagay ng guro sa :name ay bibilangin na lamang ayon sa takdang araw nito.',
    'Work counts in the grading period its due date falls in. Choose one only to count it in another.' => 'Binibilang ang gawain sa panahon ng pagmamarka na sumasaklaw sa takdang araw nito. Pumili lamang kung nais itong ibilang sa ibang panahon.',
    'Work counts in the period its due date falls in, unless its teacher chooses another. Each period has its own grade, and the final grade is their average.' => 'Binibilang ang gawain sa panahong sumasaklaw sa takdang araw nito, maliban kung pumili ng iba ang guro nito. May sariling grado ang bawat panahon, at ang pangwakas na grado ay ang karaniwan ng mga ito.',
    'Work done in class or on paper never shows as missing: until you enter its score it shows —, and a student marked absent counts as missing.' => 'Hindi kailanman lumalabas na kulang ang gawain sa klase o sa papel: hangga\'t hindi mo nailalagay ang iskor nito, — ang ipinapakita, at binibilang na kulang ang mag-aaral na nakatalang lumiban.',
    'Work handed in' => 'Mga naipasang gawain',
    'Work handed in counts published assignments and quizzes in your current classes whose due date has passed, and whether you submitted at least once. On time means submitted before the due date.' => 'Binibilang ng Mga naipasang gawain ang mga na-publish na gawain at quiz sa iyong kasalukuyang mga klase na lumampas na sa takdang araw, at kung nakapagpasa ka nang kahit isang beses. Ang Nasa oras ay nangangahulugang naipasa bago ang takdang araw.',
    'Work handed in, last 30 days' => 'Mga naipasang gawain, nakaraang 30 araw',
    'Work on :title and check it against the instructions' => 'Gawin ang :title at ihambing ito sa mga tagubilin',
    'Work that reached its due date in the last two weeks appears here.' => 'Lalabas dito ang mga gawaing umabot sa takdang araw sa nakaraang dalawang linggo.',
    'Work you have not handed in after its due date will appear here.' => 'Lalabas dito ang mga gawaing hindi mo naipasa pagkatapos ng takdang araw.',
    'Work you have submitted appears here until your teacher releases feedback.' => 'Lalabas dito ang mga naipasa mong gawain hanggang ilabas ng iyong guro ang feedback.',
    'Work your teacher excuses you from appears here. It is not counted and never shows as missing.' => 'Dito lumalabas ang mga gawaing ipinalibre sa iyo ng iyong guro. Hindi ito binibilang at hindi kailanman lumalabas na hindi naipasa.',
    'Worked example' => 'Halimbawang may solusyon',
    'Worked examples and practice items you can adapt.' => 'Mga halimbawang may solusyon at pagsasanay na maaari mong iangkop.',
    'Working on it' => 'Ginagawa pa',
    'Working…' => 'Pinoproseso…',
    'Works once and expires in :time. Creating a new link cancels this one.' => 'Isang beses lang gagana at mag-e-expire sa loob ng :time. Kapag gumawa ng bagong link, makakansela ito.',
    'Works once. Keep this slip private. Nobody at school ever sees your password.' => 'Isang beses lang gumagana. Huwag ipakita kaninuman ang slip na ito. Walang sinuman sa paaralan ang makakakita ng iyong password.',
    'Write a comment first, or select the words to save.' => 'Sumulat muna ng komento, o piliin ang mga salitang ise-save.',
    'Write at least the explanation or the activities before publishing.' => 'Isulat man lang ang paliwanag o ang mga gawain bago i-publish.',
    'Write questions below, or draft them from your class materials with the AI panel.' => 'Isulat ang mga tanong sa ibaba, o buuin ang mga ito mula sa mga materyal ng iyong klase gamit ang AI panel.',
    'Write the comment.' => 'Isulat ang komento.',
    'Write the learning objectives for this lesson.' => 'Isulat ang mga layunin sa pagkatuto para sa araling ito.',
    'Write the question.' => 'Isulat ang tanong.',
    'Written or oral works, performance tasks and examinations at 20/50/30, and 20/60/20 for EPP/TLE and MAPEH, as reported when the order came out. Type its transmutation table in from the official order.' => 'Mga pasulat o pasalitang gawain, gawaing pagganap at pagsusulit sa 20/50/30, at 20/60/20 para sa EPP/TLE at MAPEH, ayon sa iniulat nang lumabas ang kautusan. I-type ang talahanayan ng transmutasyon nito mula sa opisyal na kautusan.',
    'Written work, performance tasks and periodic assessment at 40, 40 and 20 percent, for you to adjust.' => 'Pasulat na gawain, gawaing pagganap at panaka-nakang pagtatasa sa 40, 40 at 20 porsiyento, na maaari mong iayos.',
    'Written work, performance tasks and quarterly assessment weighted by subject group (30/50/20, 40/40/20 and 20/60/20), and the order\'s transmutation table, which stays off until you check it.' => 'Pasulat na gawain, gawaing pagganap at markahang pagsusulit na may timbang ayon sa pangkat ng asignatura (30/50/20, 40/40/20 at 20/60/20), at ang talahanayan ng transmutasyon ng kautusan, na nakapatay hangga\'t hindi mo ito nasusuri.',
    'Yes' => 'Oo',
    'Yes, they agree' => 'Oo, pumapayag sila',
    'You' => 'Ikaw',
    'You acted on it, for example by asking a teacher to correct a material or tightening a policy.' => 'Inaksiyunan mo ito, halimbawa sa pamamagitan ng paghiling sa guro na itama ang isang materyal o paghigpit sa isang patakaran.',
    'You already have an open request of this type. The school will respond to it first.' => 'May bukas ka nang kahilingan na ganitong uri. Iyon muna ang tutugunan ng paaralan.',
    'You are all caught up' => 'Wala kang naiiwang gawain',
    'You are all caught up.' => 'Wala kang naiiwang gawain.',
    'You are already in :class.' => 'Kasali ka na sa :class.',
    'You are excused from this work' => 'Pinalibre ka sa gawaing ito',
    'You are excused, so there is nothing to make up.' => 'Pinalibre ka, kaya walang kailangang i-make up.',
    'You are in :count class this term.' => 'Kasali ka sa :count klase ngayong termino.',
    'You are in :count classes this term.' => 'Kasali ka sa :count klase ngayong termino.',
    'You are not in any classes yet' => 'Hindi ka pa kasali sa anumang klase',
    'You are offline' => 'Offline ka',
    'You are offline, so the quiz was not submitted yet. Your answers are kept on this device. Submit again when you are back online.' => 'Offline ka, kaya hindi pa naipasa ang quiz. Nakatago ang iyong mga sagot sa device na ito. Ipasa itong muli kapag may koneksiyon ka na.',
    'You are offline. Your answers are kept on this device and will be sent when you reconnect. Keep this page open.' => 'Offline ka. Nakatago ang iyong mga sagot sa device na ito at ipapadala kapag nakakonekta ka na muli. Panatilihing bukas ang pahinang ito.',
    'You are signed out automatically after two hours without activity.' => 'Awtomatiko kang masa-sign out pagkalipas ng dalawang oras na walang aktibidad.',
    'You are the adviser of :section' => 'Ikaw ang adviser ng :section',
    'You are this section\'s adviser.' => 'Ikaw ang adviser ng seksiyong ito.',
    'You can also delete a conversation yourself at any time.' => 'Maaari mo ring burahin ang isang usapan anumang oras.',
    'You can ask the school for a copy of your information, to correct it, or to delete it. A school administrator reviews each request. Some records, such as grades, may have to be kept by law or school policy; you will be told if so.' => 'Maaari kang humingi sa paaralan ng kopya ng iyong impormasyon, o hilingin na itama o burahin ito. Sinusuri ng administrador ng paaralan ang bawat kahilingan. Maaaring kailangang itago ang ilang talaan, gaya ng mga grado, ayon sa batas o patakaran ng paaralan; sasabihan ka kung ganoon.',
    'You can now review the correct answers.' => 'Maaari mo nang tingnan ang mga tamang sagot.',
    'You can print sign-in slips for its students.' => 'Makapagpi-print ka ng mga slip sa pag-sign in para sa mga mag-aaral nito.',
    'You can see everything about your own account, work, feedback and conversations.' => 'Nakikita mo ang lahat tungkol sa sarili mong account, gawa, feedback at mga usapan.',
    'You can use simple formatting such as **bold** and lists.' => 'Maaari kang gumamit ng simpleng pag-format gaya ng **bold** at listahan.',
    'You cannot change your answers after submitting.' => 'Hindi mo na mababago ang iyong mga sagot pagkatapos ipasa.',
    'You cannot change your own role.' => 'Hindi mo mapapalitan ang sarili mong tungkulin.',
    'You cannot change your own role. Ask another administrator.' => 'Hindi mo mapapalitan ang sarili mong tungkulin. Magtanong sa ibang administrador.',
    'You cannot deactivate your own account.' => 'Hindi mo mai-deactivate ang sarili mong account.',
    'You cannot start another attempt for this quiz.' => 'Hindi ka na makapagsisimula ng panibagong pagtatangka para sa quiz na ito.',
    'You did this in class or on paper. Your teacher will enter your score here; you get a notification when it is released.' => 'Ginawa mo ito sa klase o sa papel. Ilalagay ng iyong guro ang iyong iskor dito; makakatanggap ka ng abiso kapag inilabas na ito.',
    'You do not advise a section' => 'Wala kang seksiyong pinapayuhan',
    'You do not have access to this page' => 'Wala kang access sa pahinang ito',
    'You get this summary because you turned it on in your B.E.S.T. Learning and Interactive Study System account settings. You can turn it off there.' => 'Natatanggap mo ang buod na ito dahil binuksan mo ito sa mga setting ng iyong account sa B.E.S.T. Learning and Interactive Study System. Maaari mo itong patayin doon.',
    'You give it to the person: in person on a slip, or by email or chat.' => 'Ibibigay mo ito sa tao: personal sa isang slip, o sa email o chat.',
    'You got :score of :total. Check the explanations below.' => 'Nakakuha ka ng :score sa :total. Tingnan ang mga paliwanag sa ibaba.',
    'You have :count extra minute on the time limit.' => 'Mayroon kang :count dagdag na minuto sa takdang oras.',
    'You have :count extra minutes on the time limit.' => 'Mayroon kang :count dagdag na minuto sa takdang oras.',
    'You have :count minute to finish, starting when you open it.' => 'Mayroon kang :count minuto para matapos, simula kapag binuksan mo ito.',
    'You have :count minutes to finish, starting when you open it.' => 'Mayroon kang :count minuto para matapos, simula kapag binuksan mo ito.',
    'You have :count new notification in B.E.S.T. Learning and Interactive Study System:' => 'May :count bagong abiso ka sa B.E.S.T. Learning and Interactive Study System:',
    'You have :count new notifications in B.E.S.T. Learning and Interactive Study System:' => 'May :count bagong abiso ka sa B.E.S.T. Learning and Interactive Study System:',
    'You have :count piece of work due this week.' => 'May :count gawain kang dapat ipasa ngayong linggo.',
    'You have :count pieces of work due this week.' => 'May :count gawain kang dapat ipasa ngayong linggo.',
    'You have :count unread notification.' => 'May :count abiso kang hindi pa nababasa.',
    'You have :count unread notifications.' => 'May :count abiso kang hindi pa nababasa.',
    'You have already submitted this assignment.' => 'Naipasa mo na ang gawaing ito.',
    'You have an attempt in progress' => 'May pagtatangka kang ginagawa pa',
    'You have been signed out everywhere else.' => 'Na-sign out ka na sa lahat ng iba pang device.',
    'You have no active classes' => 'Wala kang aktibong klase',
    'You have no classes yet' => 'Wala ka pang klase',
    'You have no classes yet. Your school administrator assigns classes to teachers.' => 'Wala ka pang klase. Ang administrador ng paaralan ang nagtatalaga ng mga klase sa mga guro.',
    'You have no unread notifications.' => 'Wala kang abisong hindi pa nababasa.',
    'You have no upcoming deadlines in the next two weeks, so there is nothing to plan around yet. You can add your own study sessions on the Calendar page.' => 'Wala kang paparating na takdang araw sa susunod na dalawang linggo, kaya wala pang dapat planuhin. Maaari kang magdagdag ng sarili mong mga sesyon ng pag-aaral sa pahina ng Kalendaryo.',
    'You have sent a lot of feedback in the last hour. Try again later.' => 'Marami ka nang naipadalang feedback sa nakaraang oras. Subukan ulit mamaya.',
    'You have signed out.' => 'Naka-sign out ka na.',
    'You have used today\'s :n AI requests. The limit resets at midnight.' => 'Nagamit mo na ang :n kahilingan sa AI para ngayong araw. Magre-reset ang limitasyon pagsapit ng hatinggabi.',
    'You have used today\'s :n companion messages. The limit resets at midnight.' => 'Nagamit mo na ang :n mensahe sa companion para ngayong araw. Magre-reset ang limitasyon pagsapit ng hatinggabi.',
    'You joined :class.' => 'Sumali ka sa :class.',
    'You knew :score of :total cards.' => 'Alam mo ang :score sa :total card.',
    'You knew :score of :total cards. Review the others again later.' => 'Alam mo ang :score sa :total card. Balikan ang iba mamaya.',
    'You reached the end of the deck.' => 'Narating mo na ang dulo ng mga card.',
    'You reviewed :count question today, your school\'s number for a day. More come back tomorrow.' => 'Nakabalik-aral ka ng :count tanong ngayong araw, ang bilang na itinakda ng iyong paaralan para sa isang araw. May babalik pa bukas.',
    'You reviewed :count questions today, your school\'s number for a day. More come back tomorrow.' => 'Nakabalik-aral ka ng :count tanong ngayong araw, ang bilang na itinakda ng iyong paaralan para sa isang araw. May babalik pa bukas.',
    'You see every row before anything is saved. Codes already here are updated; codes missing from the file stay. Subjects are matched by name or code.' => 'Makikita mo ang bawat hanay bago may ma-save. Ina-update ang mga code na narito na; nananatili ang mga code na wala sa file. Itinutugma ang mga asignatura ayon sa pangalan o code.',
    'You used a recovery code. :count are left; you can make new ones in Account and preferences.' => 'Gumamit ka ng isang recovery code. :count ang natitira; maaari kang gumawa ng mga bago sa Account at mga kagustuhan.',
    'You used a recovery code. :count is left; you can make new ones in Account and preferences.' => 'Gumamit ka ng isang recovery code. :count na lang ang natitira; maaari kang gumawa ng mga bago sa Account at mga kagustuhan.',
    'You were added to :class' => 'Idinagdag ka sa :class',
    'You were not sure what to do, or something did not make sense.' => 'Hindi ka sigurado kung ano ang gagawin, o may bagay na hindi mo naintindihan.',
    'You were removed from this class, so the code cannot add you back. Ask your teacher.' => 'Inalis ka sa klaseng ito, kaya hindi ka na maibabalik ng code. Magtanong sa iyong guro.',
    'You were signed out after a period of inactivity.' => 'Na-sign out ka dahil matagal kang hindi aktibo.',
    'You will do this in class or on paper on :date. There is nothing to hand in here.' => 'Gagawin mo ito sa klase o sa papel sa :date. Walang kailangang ipasa rito.',
    'You will get a notification when feedback is released.' => 'Makatatanggap ka ng abiso kapag inilabas na ang feedback.',
    'You will type this to sign in.' => 'Ita-type mo ito para mag-sign in.',
    'Your B.E.S.T. Learning and Interactive Study System account at :school' => 'Ang iyong B.E.S.T. Learning and Interactive Study System account sa :school',
    'Your account does not include this area. If you think you should have access, ask your school administrator.' => 'Hindi kasama sa iyong account ang bahaging ito. Kung sa tingin mo ay dapat may access ka, magtanong sa administrador ng paaralan.',
    'Your account: name, username, school email if you have one, role, grade level, optional photo, language and accessibility preferences.' => 'Iyong account: pangalan, username, email sa paaralan kung mayroon ka, tungkulin, baitang, opsiyonal na larawan, wika at mga kagustuhan sa accessibility.',
    'Your adviser or a school administrator can switch the companion and AI practice off for you, for example if your parent or guardian does not agree to it. Then nothing about you is sent to an AI service, and the rest of B.E.S.T. Learning and Interactive Study System works as usual.' => 'Maaaring i-off ng iyong adviser o ng administrador ng paaralan ang companion at ang AI na pagsasanay para sa iyo, halimbawa kung hindi pumapayag ang iyong magulang o guardian. Sa ganoon, walang anumang tungkol sa iyo ang ipinapadala sa AI service, at gumagana gaya ng dati ang iba pang bahagi ng B.E.S.T. Learning and Interactive Study System.',
    'Your answer' => 'Iyong sagot',
    'Your answer:' => 'Iyong sagot:',
    'Your answers have been marked, and your teacher will release the results.' => 'Namarkahan na ang iyong mga sagot, at ilalabas ng iyong guro ang mga resulta.',
    'Your answers save as you go. Submit when you are done.' => 'Nase-save ang iyong mga sagot habang sumasagot ka. Ipasa kapag tapos ka na.',
    'Your attempts' => 'Iyong mga pagtatangka',
    'Your class materials don\'t cover this.' => 'Hindi ito saklaw ng iyong mga materyal ng klase.',
    'Your class materials may not cover this directly.' => 'Maaaring hindi direktang saklaw ng iyong mga materyal ng klase ito.',
    'Your class materials may not cover this directly. These are the closest passages:' => 'Maaaring hindi direktang saklaw ng iyong mga materyal ng klase ito. Ito ang mga pinakamalapit na sipi:',
    'Your class materials may not cover this directly. What follows is built from the closest passages.' => 'Maaaring hindi direktang saklaw ng iyong mga materyal ng klase ito. Ang kasunod ay binuo mula sa mga pinakamalapit na sipi.',
    'Your classes' => 'Iyong mga klase',
    'Your classes have no published assignments or quizzes yet.' => 'Wala pang na-publish na gawain o quiz ang iyong mga klase.',
    'Your classes, the work you submit (answers and files), the scores your teachers enter for work done in class or on paper, and the grades and feedback your teachers release to you.' => 'Iyong mga klase, ang mga gawang ipinapasa mo (mga sagot at file), ang mga iskor na inilalagay ng iyong mga guro para sa gawaing ginawa sa klase o sa papel, at ang mga grado at feedback na inilalabas sa iyo ng iyong mga guro.',
    'Your companion conversations' => 'Iyong mga usapan sa companion',
    'Your companion conversations: the questions you ask and the answers, with the sources they cite.' => 'Iyong mga usapan sa companion: ang mga tanong mo at ang mga sagot, kasama ang mga sangguniang binanggit ng mga ito.',
    'Your conversations' => 'Iyong mga usapan',
    'Your conversations are private. Teachers see only an excerpt you choose to share; administrators see only an answer someone reports.' => 'Pribado ang iyong mga usapan. Ang sipi lamang na pipiliin mong ibahagi ang nakikita ng mga guro; ang sagot lamang na may nag-report ang nakikita ng mga administrador.',
    'Your conversations will be listed here. Only you can see them.' => 'Dito ililista ang iyong mga usapan. Ikaw lang ang makakakita ng mga ito.',
    'Your conversations with the companion are private to you.' => 'Pribado sa iyo ang mga usapan mo sa companion.',
    'Your current password is not correct.' => 'Hindi tama ang iyong kasalukuyang password.',
    'Your data export is ready' => 'Handa na ang export ng iyong datos',
    'Your feedback' => 'Ang iyong feedback',
    'Your first message' => 'Iyong unang mensahe',
    'Your grade and feedback' => 'Iyong grado at feedback',
    'Your name is shown to the administrators with your feedback so they can reply. Do not include passwords or other people\'s personal information. Nothing from your companion conversations is attached.' => 'Ipinapakita sa mga administrador ang iyong pangalan kasama ng iyong feedback para makatugon sila. Huwag isama ang mga password o personal na impormasyon ng ibang tao. Walang anumang mula sa iyong mga usapan sa companion ang kalakip.',
    'Your name, username and email come from school records. To correct them, send a correction request below.' => 'Galing sa rekord ng paaralan ang iyong pangalan, username at email. Para itama ang mga ito, magpadala ng kahilingan sa pagtatama sa ibaba.',
    'Your own date.' => 'Ang sarili mong petsa.',
    'Your own date. The class date is :date.' => 'Ang sarili mong petsa. Ang petsa ng klase ay :date.',
    'Your own due date is :date.' => 'Ang sarili mong takdang araw ay :date.',
    'Your own study activity: which materials you opened, practice sets, flashcards and study sessions you planned.' => 'Sarili mong aktibidad sa pag-aaral: kung aling mga materyal ang binuksan mo, mga set ng pagsasanay, flashcards at mga sesyon ng pag-aaral na pinlano mo.',
    'Your own work' => 'Ang sarili mong gawa',
    'Your password alone will sign you in again, and your recovery codes stop working.' => 'Password mo na lang muli ang kailangan para makapag-sign in, at hihinto sa paggana ang iyong mga recovery code.',
    'Your password has been changed. Other devices have been signed out.' => 'Napalitan na ang iyong password. Na-sign out na ang ibang device.',
    'Your password has been changed. Type the code from your authenticator app to finish signing in.' => 'Napalitan na ang iyong password. I-type ang code mula sa iyong authenticator app para matapos ang pag-sign in.',
    'Your practice' => 'Iyong pagsasanay',
    'Your privacy request was completed' => 'Natapos na ang iyong kahilingan sa privacy',
    'Your privacy request was declined' => 'Tinanggihan ang iyong kahilingan sa privacy',
    'Your recovery codes' => 'Ang iyong mga recovery code',
    'Your released grades, missing and late work, and your teachers\' comments for one grading period. Print it or save it as a PDF.' => 'Ang iyong mga inilabas na grado, mga gawaing hindi naipasa o huli, at mga komento ng iyong mga guro para sa isang panahon ng pagmamarka. I-print ito o i-save bilang PDF.',
    'Your released results' => 'Iyong mga inilabas na resulta',
    'Your response' => 'Iyong sagot',
    'Your response is longer than 20,000 characters. Attach longer work as a file.' => 'Mahigit 20,000 character ang iyong sagot. Ilakip bilang file ang mas mahahabang gawa.',
    'Your result is already available on the assignment page.' => 'Makikita na ang iyong resulta sa pahina ng gawain.',
    'Your rights' => 'Iyong mga karapatan',
    'Your school adds students to classes directly. Ask your teacher or adviser if a class is missing.' => 'Direktang idinadagdag ng paaralan ang mga mag-aaral sa mga klase. Magtanong sa iyong guro o adviser kung may kulang na klase.',
    'Your school administrator chooses each section\'s adviser in Subjects and terms.' => 'Pinipili ng administrador ng paaralan ang adviser ng bawat seksiyon sa Mga asignatura at termino.',
    'Your school created a link for you to choose a new B.E.S.T. Learning and Interactive Study System password:' => 'Gumawa ang iyong paaralan ng link para makapili ka ng bagong password sa B.E.S.T. Learning and Interactive Study System:',
    'Your school has not added learning competencies for this class\'s subject yet. An administrator imports them under Subjects and terms.' => 'Hindi pa nagdaragdag ang iyong paaralan ng mga kasanayan sa pagkatuto para sa asignatura ng klaseng ito. Ini-import ito ng isang administrador sa Mga asignatura at termino.',
    'Your school has not added learning competencies for this subject yet. Once an administrator imports them, tag questions and lessons with their codes to see results here.' => 'Hindi pa nagdaragdag ang iyong paaralan ng mga kasanayan sa pagkatuto para sa asignaturang ito. Kapag na-import na ito ng isang administrador, lagyan ng kanilang mga code ang mga tanong at aralin para makita rito ang mga resulta.',
    'Your school has turned off class codes.' => 'In-off ng iyong paaralan ang mga class code.',
    'Your school has turned off class codes. Add students from the roster.' => 'In-off ng iyong paaralan ang mga class code. Magdagdag ng mga mag-aaral mula sa listahan ng klase.',
    'Your school has turned off joining classes with a code. Ask your teacher to add you.' => 'In-off ng iyong paaralan ang pagsali sa klase gamit ang code. Hilingin sa iyong guro na idagdag ka.',
    'Your school has turned off practice sets.' => 'In-off ng iyong paaralan ang mga set ng pagsasanay.',
    'Your school has turned off the review queue.' => 'Pinatay ng iyong paaralan ang pila ng pagbabalik-aral.',
    'Your school has turned off this kind of practice.' => 'In-off ng iyong paaralan ang ganitong uri ng pagsasanay.',
    'Your school has used this month\'s AI budget. It resets on the first day of next month.' => 'Naubos na ng iyong paaralan ang budget sa AI para ngayong buwan. Magre-reset ito sa unang araw ng susunod na buwan.',
    'Your school keeps companion conversations for its retention period, so they cannot be deleted early. You can archive them instead.' => 'Itinatago ng iyong paaralan ang mga usapan sa companion sa itinakdang panahon, kaya hindi maaaring burahin ang mga ito nang maaga. Maaari mo na lang i-archive ang mga ito.',
    'Your school shows up to :count question a day; questions that are due come before new ones.' => 'Hanggang :count tanong bawat araw ang ipinapakita ng iyong paaralan; nauuna ang mga takda na kaysa sa mga bago.',
    'Your school shows up to :count questions a day; questions that are due come before new ones.' => 'Hanggang :count tanong bawat araw ang ipinapakita ng iyong paaralan; nauuna ang mga takda na kaysa sa mga bago.',
    'Your school turns it into the grade shown with its transmutation table.' => 'Ginagawa ito ng iyong paaralan na gradong ipinapakita, gamit ang talahanayan ng transmutasyon nito.',
    'Your school uses points only.' => 'Puntos lamang ang ginagamit ng iyong paaralan.',
    'Your school\'s details, grade levels, logo and grading setup.' => 'Mga detalye, baitang, logo at setup sa pagmamarka ng iyong paaralan.',
    'Your school\'s list of learning competencies, for example the MATATAG curriculum\'s, with their codes. Teachers tag questions and lessons with them, and class insights report by competency.' => 'Ang listahan ng iyong paaralan ng mga kasanayan sa pagkatuto, halimbawa ang sa kurikulum na MATATAG, kasama ang kanilang mga code. Ginagamit ito ng mga guro sa mga tanong at aralin, at nag-uulat ang mga insight ng klase ayon sa kasanayan.',
    'Your section\'s adviser and your teachers can print a sign-in slip for you if you forget your password. Nobody at school ever sees your password.' => 'Makapagpi-print ng slip sa pag-sign in para sa iyo ang adviser ng iyong seksiyon at ang iyong mga guro kung makalimutan mo ang iyong password. Walang sinuman sa paaralan ang nakakakita ng iyong password.',
    'Your session has ended. Sign in again.' => 'Natapos na ang iyong session. Mag-sign in muli.',
    'Your study plan' => 'Iyong plano sa pag-aaral',
    'Your teacher asked you to revise and resubmit.' => 'Hiniling ng iyong guro na rebisahin mo ito at ipasang muli.',
    'Your teacher can give you a class code. Codes expire, so use it soon after you get it.' => 'Mabibigyan ka ng iyong guro ng class code. Nag-e-expire ang mga code, kaya gamitin ito agad.',
    'Your teacher entered this score from your work in class.' => 'Inilagay ng iyong guro ang iskor na ito mula sa iyong gawain sa klase.',
    'Your teacher excused you from this work. It is not counted and will not show as missing.' => 'Pinalibre ka ng iyong guro sa gawaing ito. Hindi ito binibilang at hindi lalabas na hindi naipasa.',
    'Your teacher excused you, so it is not counted in your grade and will not show as missing.' => 'Pinalibre ka ng iyong guro, kaya hindi ito binibilang sa iyong grado at hindi lalabas na hindi naipasa.',
    'Your teacher gave you more time' => 'Binigyan ka ng iyong guro ng dagdag na oras',
    'Your teacher has not published any lessons here yet.' => 'Wala pang na-publish na aralin dito ang iyong guro.',
    'Your teacher has returned your grade and comments.' => 'Ibinalik na ng iyong guro ang iyong grado at mga komento.',
    'Your teacher has scheduled this :kind. The instructions and questions appear when it opens.' => 'Nakaiskedyul na ng iyong guro ang :kind na ito. Lalabas ang mga tagubilin at tanong kapag nagbukas na ito.',
    'Your teacher in :class will see this answer and your note. Nothing else from the conversation is shared.' => 'Makikita ng iyong guro sa :class ang sagot na ito at ang iyong tala. Wala nang iba pang ibabahagi mula sa usapan.',
    'Your teacher marked you absent for this. Talk to them about making it up.' => 'Itinala ka ng iyong guro na lumiban dito. Kausapin siya tungkol sa make-up.',
    'Your teacher marks this answer.' => 'Ang iyong guro ang magmamarka sa sagot na ito.',
    'Your teacher or adviser gave you a slip with your username and a code. Scan its square code with a phone camera, or type the code here.' => 'Binigyan ka ng iyong guro o adviser ng slip na may username at code. I-scan ang parisukat na code nito gamit ang camera ng telepono, o i-type ang code dito.',
    'Your teacher sent this back so you can improve it. Make your changes below, then submit again.' => 'Ibinalik ito ng iyong guro para mapaganda mo pa. Gawin ang iyong mga pagbabago sa ibaba, saka ipasang muli.',
    'Your teacher will read and mark your work.' => 'Babasahin at mamarkahan ng iyong guro ang iyong gawa.',
    'Your teacher will release the correct answers.' => 'Ilalabas ng iyong guro ang mga tamang sagot.',
    'Your teacher will review it. You will get a notification when feedback is released.' => 'Susuriin ito ng iyong guro. Makatatanggap ka ng abiso kapag inilabas na ang feedback.',
    'Your teacher\'s class announcements will appear here, newest first.' => 'Lalabas dito ang mga anunsiyo ng iyong guro sa klase, mula sa pinakabago.',
    'Your teachers decide what is published and what counts as a grade.' => 'Ang iyong mga guro ang nagpapasya kung ano ang ilalabas at kung ano ang bibilangin sa grado.',
    'Your teachers see your work, grades and progress in the classes they teach. They do not see your companion conversations or your private practice unless you choose to share an excerpt.' => 'Nakikita ng iyong mga guro ang iyong gawa, grado at pag-unlad sa mga klaseng itinuturo nila. Hindi nila nakikita ang iyong mga usapan sa companion o ang iyong pribadong pagsasanay maliban kung pipiliin mong magbahagi ng sipi.',
    'Your upcoming deadlines are too close to plan sessions before them. Focus on the next due item now.' => 'Masyadong malapit na ang iyong mga paparating na takdang araw para makapagplano ng mga sesyon bago ang mga ito. Tumuon muna ngayon sa susunod na dapat ipasa.',
